import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { createInitialBoardState, type BoardState, type Player } from '../../src/types/shogi';
import type { LegalAction } from '../../src/domain/shogi/legalActions';
import type { PairedSelfPlayOutcome, PairedSelfPlayParticipantId } from '../../src/domain/shogi/pairedSelfPlayMatch';
import { runRepeatedPairedSelfPlayMatches, type RepeatedPairedSelfPlayMatchesResult,
  type RepeatedPairedSelfPlayOptions } from '../../src/domain/shogi/repeatedPairedSelfPlayMatches';
import type { SelfPlayParticipant, SelfPlayPlyRecord } from '../../src/domain/shogi/selfPlayGame';
import { resolveSearchEvaluationPreset } from '../../src/domain/shogi/searchEvaluationPresets';
import { analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch } from '../../src/domain/shogi/twoPlyAlphaBetaAi';
import type { SearchClock } from '../../src/domain/shogi/twoPlyMinimaxAi';
import { statisticKeys } from './quiescenceOrderingSuite';

/** The CLI's single explicit configuration; never changes normal game defaults. */
export const SELF_PLAY_CONFIG = Object.freeze({
  initialPosition: 'standard-hirate', pairCount: 3, maxPlies: 120, execution: 'synchronous-serial',
  participants: Object.freeze({ A: 'original', B: 'material' } as const),
  search: Object.freeze({ evaluationPreset: 'standard', moveOrdering: 'standard',
    maxTacticalDepth: 1, maxDepth: 4, timeLimitMilliseconds: 100 } as const),
} as const);

export const SELF_PLAY_LIMITATIONS = '3ペア6局はパイロット測定。同一棋譜を独立標本と見なさず、複数開始局面や定跡分岐を導入するまでは棋力差を判断できない。勝率・Elo・有意差・最適設定・既定化を判定しない。';
export const SELF_PLAY_TIMING = '100msは厳密な上限ではない。深さ1は合法手フォールバックとして時間制限から除外される。時間は未完了反復を含む探索APIの時間、統計は完了反復のみ。OS負荷・JIT・GCの影響を受ける。';

export type SelfPlayBenchmarkSettings = typeof SELF_PLAY_CONFIG.search & {
  readonly quiescenceMoveOrdering: typeof SELF_PLAY_CONFIG.participants[PairedSelfPlayParticipantId];
};
export interface SelfPlayBenchmarkDependencies {
  search?: typeof analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch;
  clock?: SearchClock;
  runner?: (options: RepeatedPairedSelfPlayOptions<SelfPlayBenchmarkSettings, SelfPlayBenchmarkSettings>) => RepeatedPairedSelfPlayMatchesResult;
}

export function createSelfPlayParticipants(dependencies: SelfPlayBenchmarkDependencies = {}) {
  const search: SelfPlayParticipant<SelfPlayBenchmarkSettings>['search'] = (state, settings) =>
    (dependencies.search ?? analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch)(
      state, settings.maxDepth, settings.timeLimitMilliseconds,
      resolveSearchEvaluationPreset(settings.evaluationPreset), dependencies.clock,
      { moveOrdering: settings.moveOrdering, quiescence: {
        maxTacticalDepth: settings.maxTacticalDepth, moveOrdering: settings.quiescenceMoveOrdering,
      } },
    );
  const participant = (id: PairedSelfPlayParticipantId): SelfPlayParticipant<SelfPlayBenchmarkSettings> => ({
    search, settings: Object.freeze({ ...SELF_PLAY_CONFIG.search,
      quiescenceMoveOrdering: SELF_PLAY_CONFIG.participants[id] }),
  });
  return { a: participant('A'), b: participant('B') };
}

export function runSelfPlayBenchmark(dependencies: SelfPlayBenchmarkDependencies = {},
  initialState: BoardState = createInitialBoardState()): RepeatedPairedSelfPlayMatchesResult {
  return (dependencies.runner ?? runRepeatedPairedSelfPlayMatches)({
    initialState, ...createSelfPlayParticipants(dependencies),
    pairCount: SELF_PLAY_CONFIG.pairCount, maxPlies: SELF_PLAY_CONFIG.maxPlies,
  });
}

/** Fixed field order ignores object insertion order and all search/outcome data.
 * Drop piece IDs are retained, matching the existing LegalAction identity. */
export function gameSignature(actions: readonly LegalAction[]): string {
  const canonical = actions.map(a => a.kind === 'move'
    ? [a.kind, a.player, a.pieceType, a.from.row, a.from.col, a.to.row, a.to.col, a.promotion]
    : [a.kind, a.player, a.pieceType, a.pieceId, a.to.row, a.to.col, a.promotion]);
  return createHash('sha256').update(JSON.stringify(canonical)).digest('hex');
}

// Decimal strings preserve bigint precision; non-finite spelling matches the existing benchmark.
export const selfPlayJson = (value: unknown): string => JSON.stringify(value, (_key, item: unknown) =>
  typeof item === 'bigint' || (typeof item === 'number' && !Number.isFinite(item)) ? String(item) : item);

const ids = ['A', 'B'] as const;
const seats = ['sente', 'gote'] as const;
const outcomeKeys = { a_win: 'aWins', b_win: 'bWins', draw: 'draws', max_plies: 'maxPlies', failed: 'failures' } as const;
type Statistic = typeof statisticKeys[number][0];
type CountField = typeof statisticKeys[number][number] | 'completedDepth';

function requireCount(value: unknown, field: string): asserts value is number | null {
  assert.ok(value === null || (typeof value === 'number' && Number.isSafeInteger(value) && value >= 0), `Invalid observation: ${field}`);
}

/** Null means unavailable, never zero. Undefined/invalid observations abort the
 * report instead of fabricating successful measurements. The game runner owns
 * legality, PV, score and terminal validation; this layer validates aggregate inputs. */
export function summarizeObservations(plies: readonly SelfPlayPlyRecord[]) {
  const unavailable: Record<string, number> = {};
  const counts = (field: CountField): bigint | null => {
    let sum = 0n, missing = 0;
    for (const ply of plies) {
      requireCount(ply[field], field);
      if (ply[field] === null) missing++;
      else sum += BigInt(ply[field]);
    }
    unavailable[field] = missing;
    return missing ? null : sum;
  };
  let elapsedMilliseconds = 0, missingTime = 0, timedOutCount = 0, missingTimeout = 0;
  const completedDepthDistribution: Record<string, number> = {};
  for (const ply of plies) {
    const time = ply.elapsedMilliseconds;
    assert.ok(time === null || (typeof time === 'number' && Number.isFinite(time) && time >= 0), 'Invalid observation: elapsedMilliseconds');
    if (time === null) missingTime++;
    else elapsedMilliseconds += time;
    assert.ok(ply.timedOut === null || typeof ply.timedOut === 'boolean', 'Invalid observation: timedOut');
    if (ply.timedOut === null) missingTimeout++;
    else if (ply.timedOut) timedOutCount++;
    requireCount(ply.completedDepth, 'completedDepth');
    const depth = ply.completedDepth === null ? 'unavailable' : String(ply.completedDepth);
    completedDepthDistribution[depth] = (completedDepthDistribution[depth] ?? 0) + 1;
    for (const [key, total] of statisticKeys) {
      requireCount(ply[key], key); requireCount(ply[total], total);
      assert.ok(ply[key] === null || ply[total] === null || ply[total]! >= ply[key]!, `Invalid observation: ${total} < ${key}`);
    }
  }
  assert.ok(Number.isFinite(elapsedMilliseconds), 'Observation time sum overflow');
  unavailable.elapsedMilliseconds = missingTime;
  unavailable.timedOut = missingTimeout;
  unavailable.completedDepth = plies.filter(p => p.completedDepth === null).length;
  const deepest = Object.fromEntries(statisticKeys.map(([key]) => [key, counts(key)])) as Record<Statistic, bigint | null>;
  const completedTotals = Object.fromEntries(statisticKeys.map(([key, total]) => [key, counts(total)])) as Record<Statistic, bigint | null>;
  return { moveCount: plies.length, elapsedMilliseconds: missingTime ? null : elapsedMilliseconds,
    completedDepthDistribution, timedOutCount: missingTimeout ? null : timedOutCount,
    deepest, completedTotals, unavailable };
}

export function summarizeSelfPlay(result: RepeatedPairedSelfPlayMatchesResult) {
  const games = result.pairs.flatMap(pair => pair.result.games.map(game => {
    const plies = game.result.plies;
    const actions = plies.map(p => p.action);
    return { pairNumber: pair.pairNumber, gameNumber: game.gameNumber,
      sente: game.sente, gote: game.gote, outcome: game.outcome,
      detail: game.result.status === 'ended' ? game.result.gameResult
        : game.result.status === 'failed' ? game.result.failure : { reason: 'max_plies' },
      plyCount: plies.length,
      participants: Object.fromEntries(ids.map(id => [id,
        summarizeObservations(plies.filter(p => game[p.player] === id))])),
      actions, signature: gameSignature(actions), plies,
    };
  }));
  const outcomes = { ...result.summary };
  for (const [outcome, key] of Object.entries(outcomeKeys)) {
    assert.equal(outcomes[key], BigInt(games.filter(g => g.outcome === outcome).length), `Inconsistent outcome count: ${key}`);
  }
  const totalGames = BigInt(games.length);
  const outcomeCountSum = Object.values(outcomes).reduce((sum, n) => sum + n, 0n);
  assert.equal(totalGames, BigInt(result.pairs.length) * 2n, 'Two games required per pair');
  assert.equal(totalGames, outcomeCountSum, 'Inconsistent total game count');
  const participantSummary = (id: PairedSelfPlayParticipantId, seat?: Player) => {
    const selected = games.filter(g => seat === undefined || g[seat] === id);
    const ownWin: PairedSelfPlayOutcome = id === 'A' ? 'a_win' : 'b_win';
    const otherWin: PairedSelfPlayOutcome = id === 'A' ? 'b_win' : 'a_win';
    return { games: selected.length, outcomes: {
      wins: selected.filter(g => g.outcome === ownWin).length,
      losses: selected.filter(g => g.outcome === otherWin).length,
      draws: selected.filter(g => g.outcome === 'draw').length,
      maxPlies: selected.filter(g => g.outcome === 'max_plies').length,
      failures: selected.filter(g => g.outcome === 'failed').length,
    }, ...summarizeObservations(selected.flatMap(g => g.plies.filter(p => g[p.player] === id))) };
  };
  const frequencies = new Map<string, { signature: string; count: number; games: string[] }>();
  for (const game of games) {
    const item = frequencies.get(game.signature) ?? { signature: game.signature, count: 0, games: [] };
    item.count++; item.games.push(`${game.pairNumber}/${game.gameNumber}`);
    frequencies.set(game.signature, item);
  }
  return { games, summary: { outcomes, totalGames, outcomeCountSum, consistent: totalGames === outcomeCountSum,
    participants: Object.fromEntries(ids.map(id => [id, participantSummary(id)])),
    bySeat: Object.fromEntries(seats.map(seat => [seat,
      Object.fromEntries(ids.map(id => [id, participantSummary(id, seat)]))])),
    uniqueSignatures: frequencies.size, duplicateGames: games.length - frequencies.size,
    signatureFrequencies: [...frequencies.values()],
  } };
}

/** Output is deliberately separate from the synchronous game runner. Full ply
 * observations remain available even when a later observation/summary fails. */
export function runSelfPlayCli(dependencies: SelfPlayBenchmarkDependencies = {}, write = console.log): 0 | 1 {
  write(`CONFIG ${selfPlayJson(SELF_PLAY_CONFIG)}`);
  write('A=original / B=material。標準平手初期局面。各ペアはA先手/B後手→B先手/A後手。全局同期・直列実行。');
  write(SELF_PLAY_TIMING); write(SELF_PLAY_LIMITATIONS);
  try {
    const result = runSelfPlayBenchmark(dependencies);
    for (const pair of result.pairs) for (const game of pair.result.games) {
      write(`RECORD ${selfPlayJson({ pairNumber: pair.pairNumber, gameNumber: game.gameNumber,
        sente: game.sente, gote: game.gote, outcome: game.outcome, status: game.result.status,
        plies: game.result.plies })}`);
    }
    const report = summarizeSelfPlay(result);
    for (const { plies: _plies, ...game } of report.games) {
      write(`ペア${game.pairNumber} 第${game.gameNumber}局: 先手${game.sente}/後手${game.gote}, ${game.outcome}, ${game.plyCount}ply`);
      write(`GAME ${selfPlayJson(game)}`);
    }
    write(`SUMMARY ${selfPlayJson(report.summary)}`);
    write(`結果: ${selfPlayJson(report.summary.outcomes)}; ユニーク棋譜=${report.summary.uniqueSignatures}; 重複=${report.summary.duplicateGames}`);
    return result.summary.failures > 0n ? 1 : 0;
  } catch (error) {
    write(`ERROR ${selfPlayJson({ message: error instanceof Error ? error.message : String(error) })}`);
    return 1;
  }
}

import { createInitialBoardState, type BoardState, type Piece, type PieceType, type Player } from '../../src/types/shogi';
import { isPlayerInCheck } from '../../src/domain/shogi/checkmate';
import { executeLegalAction, getLegalActions, type LegalAction } from '../../src/domain/shogi/legalActions';
import { normalizePositionHistory } from '../../src/domain/shogi/repetition';
import { normalizePositionSnapshots } from '../../src/domain/shogi/replay';

export interface SelfPlayScenario {
  readonly id: string;
  readonly name: string;
  readonly purpose: string;
  readonly provenance: string;
  readonly phase: ScenarioPhase;
  readonly sideToMove: Player;
  readonly create: () => BoardState;
}

export type ScenarioPhase = 'opening' | 'middlegame' | 'endgame';

type BookMove = Readonly<{
  kind: 'move';
  player: Player;
  pieceType: PieceType;
  from: readonly [row: number, col: number];
  to: readonly [row: number, col: number];
  promotion: 'none' | 'promote' | 'decline';
}>;

type BookDrop = Readonly<{
  kind: 'drop'; player: Player; pieceType: Exclude<PieceType, 'king'>;
  to: readonly [row: number, col: number];
}>;
type BookAction = BookMove | BookDrop;
type HandPieceType = Exclude<PieceType, 'king'>;
type ScenarioPlacement = readonly [number, number, PieceType, Player];

interface ScenarioHands {
  readonly sente?: readonly HandPieceType[];
  readonly gote?: readonly HandPieceType[];
}

function replayBookLine(id: string, expectedTurn: Player, moves: readonly BookAction[]): BoardState {
  let state = createInitialBoardState();
  for (const [index, expected] of moves.entries()) {
    const matches = getLegalActions(state).filter((action): action is LegalAction => expected.kind === 'drop'
      ? action.kind === 'drop' && action.player === expected.player && action.pieceType === expected.pieceType &&
        action.to.row === expected.to[0] && action.to.col === expected.to[1]
      : action.kind === 'move' && action.player === expected.player && action.pieceType === expected.pieceType &&
        action.from.row === expected.from[0] && action.from.col === expected.from[1] &&
        action.to.row === expected.to[0] && action.to.col === expected.to[1] && action.promotion === expected.promotion,
    );
    if (matches.length !== 1) {
      throw new Error(`scenario=${id} book ply=${index + 1}: expected exactly one semantic legal move, found ${matches.length}.`);
    }
    const execution = executeLegalAction(state, matches[0], { proposer: 'local_ai' });
    if (execution.type !== 'applied') {
      throw new Error(`scenario=${id} book ply=${index + 1}: legal move application returned ${execution.type}.`);
    }
    state = execution.state;
  }
  if (state.turn !== expectedTurn) throw new Error(`scenario=${id}: expected ${expectedTurn} to move, found ${state.turn}.`);
  return state;
}

/**
 * Builds a deliberately sparse, deterministic research position through the
 * same normalized BoardState path used by the quiescence benchmark fixtures.
 * These are composed positions, not claims about a historical game record.
 */
function composeResearchPosition(
  id: string,
  turn: Player,
  placements: readonly ScenarioPlacement[],
  hands: ScenarioHands = {},
): BoardState {
  const state = createInitialBoardState();
  state.recordId = `killer-suite-${id}`;

  for (const row of state.squares) for (const square of row) square.piece = null;
  for (const [row, col, type, player] of placements) {
    state.squares[row][col].piece = { id: `${id}-board-${player}-${type}-${row}-${col}`, type, player };
  }

  const createHand = (player: Player, pieces: readonly HandPieceType[] = []): Piece[] =>
    pieces.map((type, index) => ({ id: `${id}-hand-${player}-${type}-${index}`, type, player }));
  state.senteHand = createHand('sente', hands.sente);
  state.goteHand = createHand('gote', hands.gote);
  state.turn = turn;
  state.status = isPlayerInCheck(state, turn) ? 'check' : 'active';

  return normalizePositionSnapshots(normalizePositionHistory(state));
}

const move = (player: Player, pieceType: PieceType, from: BookMove['from'], to: BookMove['to'],
  promotion: BookMove['promotion'] = 'none'): BookMove => ({ kind: 'move', player, pieceType, from, to, promotion });

/** Fixed, legal, independently-created starts for the research-only suite. */
export const QUIESCENCE_ORDERING_SELF_PLAY_SCENARIOS: readonly SelfPlayScenario[] = Object.freeze([
  Object.freeze({
    id: 'standard-hirate', name: '平手初期局面', purpose: '既存パイロットとの連続性を保つ基準局面。',
    provenance: 'createInitialBoardState()（固定手順なし）。', phase: 'opening', sideToMove: 'sente', create: () => createInitialBoardState(),
  }),
  Object.freeze({
    id: 'rook-pawn-opening-76-34-26-84', name: '▲7六歩 △3四歩 ▲2六歩 △8四歩後',
    purpose: '角道と飛車先の異なる定跡分岐を含める。',
    provenance: '平手から ▲7六歩 △3四歩 ▲2六歩 △8四歩 を公開合法手APIで再生。',
    phase: 'opening', sideToMove: 'sente', create: () => replayBookLine('rook-pawn-opening-76-34-26-84', 'sente', [
      move('sente', 'pawn', [6, 2], [5, 2]), move('gote', 'pawn', [2, 6], [3, 6]),
      move('sente', 'pawn', [6, 7], [5, 7]), move('gote', 'pawn', [2, 1], [3, 1]),
    ]),
  }),
  Object.freeze({
    id: 'rook-pawn-exchange-26-84-25-85', name: '▲2六歩 △8四歩 ▲2五歩 △8五歩後',
    purpose: '双方の飛車先を一段進めた別の定跡分岐を含める。',
    provenance: '平手から ▲2六歩 △8四歩 ▲2五歩 △8五歩 を公開合法手APIで再生。',
    phase: 'opening', sideToMove: 'sente', create: () => replayBookLine('rook-pawn-exchange-26-84-25-85', 'sente', [
      move('sente', 'pawn', [6, 7], [5, 7]), move('gote', 'pawn', [2, 1], [3, 1]),
      move('sente', 'pawn', [5, 7], [4, 7]), move('gote', 'pawn', [3, 1], [4, 1]),
    ]),
  }),
  Object.freeze({
    id: 'quiet-double-static-rook-middlegame', name: '相居飛車の静かな駒組み',
    purpose: '玉と金銀の整備が進み、初期局面より候補手が増えた非王手の静かな中盤を観察する。',
    provenance: '平手から相居飛車の基本的な駒組みを公開合法手APIで20手再生した固定手順。実戦棋譜であるとは主張しない。',
    phase: 'middlegame', sideToMove: 'sente', create: () => replayBookLine('quiet-double-static-rook-middlegame', 'sente', [
      move('sente', 'pawn', [6, 2], [5, 2]), move('gote', 'pawn', [2, 6], [3, 6]),
      move('sente', 'pawn', [6, 7], [5, 7]), move('gote', 'pawn', [2, 1], [3, 1]),
      move('sente', 'pawn', [5, 7], [4, 7]), move('gote', 'pawn', [3, 1], [4, 1]),
      move('sente', 'bishop', [7, 1], [6, 2]), move('gote', 'gold', [0, 5], [1, 6]),
      move('sente', 'silver', [8, 2], [7, 3]), move('gote', 'silver', [0, 6], [1, 5]),
      move('sente', 'king', [8, 4], [7, 4]), move('gote', 'king', [0, 4], [1, 4]),
      move('sente', 'king', [7, 4], [7, 5]), move('gote', 'king', [1, 4], [1, 3]),
      move('sente', 'gold', [8, 5], [7, 4]), move('gote', 'gold', [0, 3], [1, 4]),
      move('sente', 'silver', [8, 6], [7, 6]), move('gote', 'pawn', [2, 2], [3, 2]),
      move('sente', 'pawn', [6, 3], [5, 3]), move('gote', 'pawn', [2, 3], [3, 3]),
    ]),
  }),
  Object.freeze({
    id: 'rook-pawn-recapture-middlegame', name: '飛車先の歩交換と取り返し',
    purpose: '歩交換、飛車による取り返し、持ち駒の発生を含め、候補手順序の影響を観察しやすくする。',
    provenance: '平手から飛車先の歩交換を公開合法手APIで再生した固定手順。実戦棋譜であるとは主張しない。',
    phase: 'middlegame', sideToMove: 'sente', create: () => replayBookLine('rook-pawn-recapture-middlegame', 'sente', [
      move('sente', 'pawn', [6, 7], [5, 7]), move('gote', 'pawn', [2, 1], [3, 1]),
      move('sente', 'pawn', [5, 7], [4, 7]), move('gote', 'pawn', [3, 1], [4, 1]),
      move('sente', 'pawn', [4, 7], [3, 7]), move('gote', 'pawn', [2, 7], [3, 7]),
      move('sente', 'rook', [7, 7], [3, 7]), move('gote', 'pawn', [4, 1], [5, 1]),
      move('sente', 'pawn', [6, 1], [5, 1]), move('gote', 'rook', [1, 1], [5, 1]),
    ]),
  }),
  Object.freeze({
    id: 'check-evasion-endgame', name: '構成終盤の王手回避',
    purpose: '駒数を大幅に減らした後手玉への飛車王手で、王手回避・合駒を含む探索木を比べる。',
    provenance: '実戦棋譜ではない。quiescence benchmark と同じ正規化済み BoardState 構築パターンで作った、盤上8枚・双方持ち駒ありの決定的な研究用構成局面。',
    phase: 'endgame', sideToMove: 'gote', create: () => composeResearchPosition('check-evasion-endgame', 'gote', [
      [8, 4, 'king', 'sente'], [0, 4, 'king', 'gote'], [4, 4, 'rook', 'sente'],
      [2, 2, 'silver', 'sente'], [6, 6, 'gold', 'sente'], [1, 3, 'gold', 'gote'],
      [1, 5, 'silver', 'gote'], [3, 7, 'bishop', 'gote'],
    ], { sente: ['pawn', 'knight'], gote: ['pawn', 'gold'] }),
  }),
  Object.freeze({
    id: 'hand-drop-endgame', name: '構成終盤の持ち駒歩打ち',
    purpose: '駒数を大幅に減らした後手番で、通常手と合法な持ち駒歩打ちが混ざる探索順を比べる。',
    provenance: '実戦棋譜ではない。quiescence benchmark と同じ正規化済み BoardState 構築パターンで作った、盤上7枚・双方持ち駒ありの決定的な研究用構成局面。',
    phase: 'endgame', sideToMove: 'gote', create: () => composeResearchPosition('hand-drop-endgame', 'gote', [
      [8, 4, 'king', 'sente'], [0, 4, 'king', 'gote'], [5, 2, 'rook', 'sente'],
      [6, 6, 'gold', 'sente'], [3, 6, 'bishop', 'gote'], [2, 2, 'silver', 'gote'],
      [4, 5, 'pawn', 'sente'],
    ], { sente: ['silver', 'knight'], gote: ['pawn', 'gold'] }),
  }),
]);

import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { createPositionKey } from '../../src/domain/shogi/repetition';
import { runPairedSelfPlayMatch, type PairedSelfPlayMatchResult } from '../../src/domain/shogi/pairedSelfPlayMatch';
import type { LegalAction } from '../../src/domain/shogi/legalActions';
import type { SelfPlayParticipant } from '../../src/domain/shogi/selfPlayGame';
import { SELF_PLAY_CONFIG, createSelfPlayParticipants, gameSignature, selfPlayJson, summarizeSelfPlay,
  type SelfPlayBenchmarkDependencies, type SelfPlayBenchmarkSettings } from './quiescenceOrderingSelfPlay';
import { QUIESCENCE_ORDERING_SELF_PLAY_SCENARIOS, type SelfPlayScenario } from './quiescenceOrderingSelfPlayScenarios';

export const SELF_PLAY_SUITE_CONFIG = Object.freeze({
  scenarioIds: Object.freeze(QUIESCENCE_ORDERING_SELF_PLAY_SCENARIOS.map(scenario => scenario.id)),
  pairsPerScenario: 1,
  execution: 'synchronous-serial',
} as const);

export type PairRunner = (options: {
  initialState: ReturnType<SelfPlayScenario['create']>;
  a: SelfPlayParticipant<SelfPlayBenchmarkSettings>;
  b: SelfPlayParticipant<SelfPlayBenchmarkSettings>;
  maxPlies: number;
}) => PairedSelfPlayMatchResult;

export interface SelfPlaySuiteDependencies extends Omit<SelfPlayBenchmarkDependencies, 'runner'> {
  runner?: PairRunner;
}

export class SelfPlaySuiteScenarioError extends Error {
  constructor(readonly scenarioId: string, cause: unknown) {
    super(`scenario=${scenarioId}: ${cause instanceof Error ? cause.message : String(cause)}`);
    this.name = 'SelfPlaySuiteScenarioError';
  }
}

export function positionGameSignature(initialPositionKey: string, actions: readonly LegalAction[]): string {
  return createHash('sha256').update(JSON.stringify([initialPositionKey, gameSignature(actions)])).digest('hex');
}

const summaryKeys = ['aWins', 'bWins', 'draws', 'maxPlies', 'failures'] as const;
type SummaryKey = typeof summaryKeys[number];
type SuiteOutcomes = Record<SummaryKey, bigint>;

function singlePairSummary(pair: PairedSelfPlayMatchResult): SuiteOutcomes {
  return Object.fromEntries(summaryKeys.map(key => [key, BigInt(pair.summary[key])])) as SuiteOutcomes;
}

function assertOutcomeInvariant(summary: SuiteOutcomes, expectedGames: bigint, label: string): void {
  const count = summaryKeys.reduce((total, key) => total + summary[key], 0n);
  assert.equal(count, expectedGames, `${label}: outcome counts must equal game count.`);
}

function summarizePair(pair: PairedSelfPlayMatchResult) {
  return summarizeSelfPlay({ pairs: [{ pairNumber: 1, result: pair }], summary: singlePairSummary(pair) });
}

export interface SelfPlaySuiteScenarioResult {
  readonly scenarioId: string;
  readonly scenarioName: string;
  readonly provenance: string;
  readonly initialPositionKey: string;
  readonly executionOrder: number;
  readonly pair: PairedSelfPlayMatchResult;
  readonly summary: ReturnType<typeof summarizePair>['summary'];
  readonly games: Array<ReturnType<typeof summarizePair>['games'][number] & { positionSignature: string }>;
}

export interface SelfPlaySuiteResult {
  readonly scenarios: SelfPlaySuiteScenarioResult[];
  readonly summary: {
    readonly outcomes: SuiteOutcomes;
    readonly totalGames: bigint;
    readonly outcomeCountSum: bigint;
    readonly consistent: boolean;
    readonly uniquePositionSignatures: number;
    readonly duplicateGames: number;
    readonly signatureFrequencies: Array<{ signature: string; count: number; games: string[] }>;
  };
}

export interface SelfPlaySuiteHooks {
  readonly onScenarioStart?: (scenario: SelfPlayScenario, executionOrder: number, initialPositionKey: string) => void;
  readonly onScenarioComplete?: (scenario: SelfPlaySuiteScenarioResult) => void;
}

/** Runs exactly one existing A/B seat-swapped pair per catalogued start. */
export function runSelfPlaySuite(dependencies: SelfPlaySuiteDependencies = {},
  scenarios: readonly SelfPlayScenario[] = QUIESCENCE_ORDERING_SELF_PLAY_SCENARIOS,
  hooks: SelfPlaySuiteHooks = {}): SelfPlaySuiteResult {
  assert.equal(new Set(scenarios.map(scenario => scenario.id)).size, scenarios.length, 'Scenario IDs must be unique.');
  const { runner, ...searchDependencies } = dependencies;
  const participants = createSelfPlayParticipants(searchDependencies);
  const results: SelfPlaySuiteScenarioResult[] = [];
  const frequencies = new Map<string, { signature: string; count: number; games: string[] }>();
  const outcomes: SuiteOutcomes = { aWins: 0n, bWins: 0n, draws: 0n, maxPlies: 0n, failures: 0n };
  for (const [index, scenario] of scenarios.entries()) {
    let initialPositionKey = '';
    try {
      const initialState = scenario.create();
      if (initialState.turn !== scenario.sideToMove) {
        throw new Error(`scenario turn must be ${scenario.sideToMove}, found ${initialState.turn}.`);
      }
      initialPositionKey = createPositionKey(initialState);
      hooks.onScenarioStart?.(scenario, index + 1, initialPositionKey);
      const pair = (runner ?? runPairedSelfPlayMatch)({
        initialState, ...participants, maxPlies: SELF_PLAY_CONFIG.maxPlies,
      });
      const report = summarizePair(pair);
      assertOutcomeInvariant(singlePairSummary(pair), 2n, `scenario=${scenario.id}`);
      const games = report.games.map(game => ({ ...game,
        positionSignature: positionGameSignature(initialPositionKey, game.actions),
      }));
      for (const game of games) {
        const item = frequencies.get(game.positionSignature) ?? { signature: game.positionSignature, count: 0, games: [] };
        item.count++; item.games.push(`${scenario.id}/${game.pairNumber}/${game.gameNumber}`);
        frequencies.set(game.positionSignature, item);
      }
      for (const key of summaryKeys) outcomes[key] += BigInt(pair.summary[key]);
      const entry: SelfPlaySuiteScenarioResult = {
        scenarioId: scenario.id, scenarioName: scenario.name, provenance: scenario.provenance,
        initialPositionKey, executionOrder: index + 1, pair, summary: report.summary, games,
      };
      results.push(entry);
      hooks.onScenarioComplete?.(entry);
    } catch (error) {
      throw new SelfPlaySuiteScenarioError(scenario.id, error);
    }
  }
  const totalGames = BigInt(results.length * 2);
  assert.equal(totalGames, BigInt(results.length) * 2n, 'Suite game count must use two games per executed scenario.');
  assertOutcomeInvariant(outcomes, totalGames, 'suite');
  const outcomeCountSum = summaryKeys.reduce((total, key) => total + outcomes[key], 0n);
  return { scenarios: results, summary: { outcomes, totalGames, outcomeCountSum,
    consistent: totalGames === outcomeCountSum,
    uniquePositionSignatures: frequencies.size, duplicateGames: Number(totalGames) - frequencies.size,
    signatureFrequencies: [...frequencies.values()],
  } };
}

export function runSelfPlaySuiteCli(dependencies: SelfPlaySuiteDependencies = {}, write = console.log): 0 | 1 {
  write(`SUITE_CONFIG ${selfPlayJson({ ...SELF_PLAY_SUITE_CONFIG, search: SELF_PLAY_CONFIG.search, participants: SELF_PLAY_CONFIG.participants, maxPlies: SELF_PLAY_CONFIG.maxPlies })}`);
  try {
    const result = runSelfPlaySuite(dependencies, QUIESCENCE_ORDERING_SELF_PLAY_SCENARIOS, {
      onScenarioStart: (scenario, executionOrder, initialPositionKey) => write(`SCENARIO_START ${selfPlayJson({
        scenarioId: scenario.id, scenarioName: scenario.name, provenance: scenario.provenance, executionOrder, initialPositionKey,
      })}`),
      onScenarioComplete: scenario => {
        for (const game of scenario.games) {
          write(`RECORD ${selfPlayJson({ scenarioId: scenario.scenarioId, pairNumber: game.pairNumber, gameNumber: game.gameNumber, plies: game.plies })}`);
          const { plies: _plies, ...summary } = game;
          write(`GAME ${selfPlayJson({ scenarioId: scenario.scenarioId, ...summary })}`);
        }
        write(`SCENARIO_SUMMARY ${selfPlayJson({ scenarioId: scenario.scenarioId, scenarioName: scenario.scenarioName,
          provenance: scenario.provenance, initialPositionKey: scenario.initialPositionKey, executionOrder: scenario.executionOrder,
          summary: scenario.summary })}`);
      },
    });
    write(`SUITE_SUMMARY ${selfPlayJson(result.summary)}`);
    return result.summary.outcomes.failures > 0n ? 1 : 0;
  } catch (error) {
    const scenarioId = error instanceof SelfPlaySuiteScenarioError ? error.scenarioId : undefined;
    write(`ERROR ${selfPlayJson({ scenarioId, message: error instanceof Error ? error.message : String(error) })}`);
    return 1;
  }
}

scripts/benchmarks/quiescenceOrderingSui:
import { validatePartialRoot } from '../../src/application/partialRootValidation';
import assert from 'node:assert/strict';
import type { BoardState } from '../../src/types/shogi';
import { createComparisonSnapshot } from '../../src/domain/shogi/evaluationPresetComparison';
import { executeLegalAction, getLegalActions } from '../../src/domain/shogi/legalActions';
import { cloneBoardState } from '../../src/domain/shogi/replay';
import { evaluateSearchPositionBreakdown, evaluateNoLegalActionsPositionBreakdown } from '../../src/domain/shogi/twoPlyMinimaxAi';
import { analyzeAlphaBetaSearch, analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch,
  type AlphaBetaSearchResult, type TimeLimitedIterativeDeepeningAlphaBetaSearchResult } from '../../src/domain/shogi/twoPlyAlphaBetaAi';
import { formatLegalActionNotation, validateAndFormatPrincipalVariation } from '../../src/application/searchPrincipalVariation';
import { formatSenteEvaluation } from '../../src/components/shogi/searchEvaluationDisplay';
import { QUIESCENCE_BENCHMARK_POSITIONS, type BenchmarkPosition } from './quiescencePositions';
import type { BenchmarkDependencies, BenchmarkMode } from './quiescenceSuite';

export const ORDERING_SETTINGS = [
  { maxTacticalDepth: 1, moveOrdering: 'original' },
  { maxTacticalDepth: 1, moveOrdering: 'material' },
  { maxTacticalDepth: 2, moveOrdering: 'original' },
  { maxTacticalDepth: 2, moveOrdering: 'material' },
] as const;
export type Setting = (typeof ORDERING_SETTINGS)[number] & { readonly killerMoves?: boolean };
export type SearchResult = AlphaBetaSearchResult | TimeLimitedIterativeDeepeningAlphaBetaSearchResult;
export type OrderingResult = { setting: Setting; search: SearchResult; pv: string[] };
/** Per-invocation timed-search inputs. They are never retained as global state. */
export interface TimedSearchOptions {
  readonly timeLimitMilliseconds: number;
  readonly maxDepth: number;
}
export const DEFAULT_TIMED_SEARCH_OPTIONS: TimedSearchOptions = Object.freeze({
  timeLimitMilliseconds: 1000,
  maxDepth: 4,
});
export type OrderingCase = { position: BenchmarkPosition; mode: BenchmarkMode } & (
  { ok: true; turn: BoardState['turn']; results: OrderingResult[] } | { ok: false; error: string }
);
export const statisticKeys = [
  ['visitedPositionCount', 'totalVisitedPositionCount'], ['cutoffCount', 'totalCutoffCount'],
  ['skippedActionCount', 'totalSkippedActionCount'], ['quiescenceLeafCount', 'totalQuiescenceLeafCount'],
  ['quiescenceVisitedPositionCount', 'totalQuiescenceVisitedPositionCount'],
  ['quiescenceCutoffCount', 'totalQuiescenceCutoffCount'], ['quiescenceSkippedActionCount', 'totalQuiescenceSkippedActionCount'],
] as const;
const counts = (r: SearchResult, total = false) => statisticKeys.map(([key, sum]) => total && 'iterations' in r ? r[sum] : r[key]);
const formatCounts = (v: number[]) => `通常[訪問=${v[0]}, cutoff=${v[1]}, skip=${v[2]}] 静止[開始葉=${v[3]}, 訪問=${v[4]}, cutoff=${v[5]}, skip=${v[6]}]`;

/** Validate outside measured search time. Replay EVERY completed PV and compare
 * the actual leaf's complete evaluation breakdown, not just the terminal flag. */
function validatePass(state: BoardState, result: AlphaBetaSearchResult, depth: number, extension: number): string[] {
  assert.equal(result.depth, depth, '探索深さ');
  assert.ok(Number.isFinite(result.elapsedMilliseconds) && result.elapsedMilliseconds >= 0, '参考時間');
  assert.ok(counts(result).every(v => Number.isSafeInteger(v) && v >= 0), '探索統計');
  assert.equal(result.rootLegalActionCount, getLegalActions(state).length, 'root合法手数');
  assert.ok(result.quiescenceLeafCount <= result.visitedPositionCount, '静止開始葉数');
  assert.ok(result.principalVariation.length <= depth + extension, 'PV上限');
  let leaf = cloneBoardState(state);
  let pv: string[] = [];
  if (result.selectedAction === null) {
    assert.equal(result.rootLegalActionCount, 0, '合法手があるのに手なし');
    assert.equal(result.selectedEvaluation, null);
    assert.equal(result.principalVariation.length, 0);
    assert.ok(counts(result).every(v => v === 0));
  } else {
    const formatted = validateAndFormatPrincipalVariation(state, result, Math.max(depth, result.principalVariation.length), true);
    assert.ok(formatted, '推奨手/PVが不正');
    pv = formatted;
    for (const action of result.principalVariation) {
      const execution = executeLegalAction(leaf, action);
      assert.equal(execution.type, 'applied', 'PV実行');
      if (execution.type === 'applied') leaf = execution.state;
    }
    assert.equal(result.selectedEvaluation, result.evaluationBreakdown.total, '評価値と内訳');
  }
  assert.deepStrictEqual(result.evaluationBreakdown, evaluateSearchPositionBreakdown(leaf, state.turn), 'PV末端の評価内訳');
  return pv;
}

export function validateOrderingResult(state: BoardState, result: SearchResult, mode: BenchmarkMode, extension: number,
  timedOptions: TimedSearchOptions = DEFAULT_TIMED_SEARCH_OPTIONS): string[] {
  if (mode === 'fixed') {
    assert.ok(!('iterations' in result), '固定深さ結果');
    return validatePass(state, result, 3, extension);
  }
  assert.ok('iterations' in result, '完了反復なし');
  assert.equal(result.requestedMaxDepth, timedOptions.maxDepth);
  if (state.status === 'ended') assert.equal(result.resultSource,'ended-position','終局root分類');
  if (result.resultSource === 'ended-position') {
    assert.equal(state.status, 'ended');
    assert.deepStrictEqual(result.terminalResult, state.result, '元の終局理由');
    assert.equal(result.depth, 0);
    assert.equal(result.completedDepth, 0);
    assert.equal(result.timedOut, false);
    assert.equal(result.rootLegalActionCount, 0);
    assert.equal(result.selectedAction, null);
    assert.deepStrictEqual(result.iterations, []);
    assert.deepStrictEqual(result.principalVariation, []);
    assert.deepStrictEqual(result.evaluationBreakdown, evaluateSearchPositionBreakdown(state,state.turn));
    assert.equal(result.selectedEvaluation, result.evaluationBreakdown.total);
    assert.ok(Number.isFinite(result.elapsedMilliseconds) && result.elapsedMilliseconds>=0);
    for (const [key,total] of statisticKeys) {
      assert.equal(result[key],0,`終局root:${key}`);
      assert.equal(result[total],0,`完了反復合計:${total}`);
    }
    return [];
  }
  if (result.resultSource === 'no-legal-actions') {
    assert.notEqual(state.status,'ended');
    assert.equal(getLegalActions(state).length,0);
    assert.equal(result.terminalResult,undefined);
    assert.equal(result.depth,0);
    assert.equal(result.completedDepth,0);
    assert.equal(result.timedOut,false);
    assert.equal(result.selectedAction,null);
    assert.equal(result.rootLegalActionCount,0);
    assert.deepStrictEqual(result.iterations,[]);
    assert.deepStrictEqual(result.principalVariation,[]);
    const expected = evaluateNoLegalActionsPositionBreakdown(state,state.turn);
    assert.deepStrictEqual(result.evaluationBreakdown,expected);
    assert.equal(result.selectedEvaluation,expected.total);
    assert.ok(Number.isFinite(result.elapsedMilliseconds) && result.elapsedMilliseconds>=0);
    assert.ok(statisticKeys.every(([key,total])=>result[key]===0 && result[total]===0));
    return [];
  }
  assert.ok(Number.isSafeInteger(result.completedDepth) && result.completedDepth >= 0 && result.completedDepth <= timedOptions.maxDepth);
  assert.equal(result.timedOut, result.completedDepth < timedOptions.maxDepth);
  assert.equal(result.iterations.length, result.completedDepth);
  if (result.resultSource === 'partial-root') {
    const pv = validatePartialRoot(state, result, extension); assert.ok(pv); return pv;
  }
  if (result.completedDepth === 0) {
    const legal = getLegalActions(state);
    assert.equal(result.resultSource, 'fallback');
    assert.equal(result.depth, 0);
    assert.equal(result.rootLegalActionCount, legal.length);
    assert.deepStrictEqual(result.selectedAction, legal[0] ?? null);
    assert.equal(result.selectedEvaluation, null);
    assert.equal(result.evaluationBreakdown, null);
    assert.deepStrictEqual(result.principalVariation, []);
    assert.ok(statisticKeys.every(([key, total]) => result[key] === 0 && result[total] === 0));
    return result.selectedAction ? [formatLegalActionNotation(state, result.selectedAction)] : [];
  }
  assert.equal(result.resultSource, 'completed-iteration');
  result.iterations.forEach((pass, i) => validatePass(state, pass, i + 1, extension));
  const deepest = result.iterations[result.completedDepth - 1];
  const { elapsedMilliseconds: _elapsed, ...selected } = result;
  for (const [key, value] of Object.entries(deepest)) {
    if (key !== 'elapsedMilliseconds') assert.deepStrictEqual(selected[key as keyof typeof selected], value, `最深完了反復:${key}`);
  }
  for (const [key, total] of statisticKeys) {
    assert.equal(result[total], result.iterations.reduce((sum, pass) => sum + pass[key], 0), `完了反復合計:${total}`);
  }
  assert.ok(result.evaluationBreakdown);
  return validatePass(state, result as AlphaBetaSearchResult, result.completedDepth, extension);
}

/** Shared single API call for both CLIs. Each invocation owns a new frozen
 * snapshot; the timed API creates its own deadline. Capture before validation
 * so the repeated runner can retain even invalid returned results. */
export function runOrderingTrial(input: BoardState, mode: BenchmarkMode, setting: Setting,
  dependencies: BenchmarkDependencies = {}, capture?: (search: SearchResult) => void,
  timedOptions: TimedSearchOptions = DEFAULT_TIMED_SEARCH_OPTIONS): OrderingResult {
  const before = structuredClone(input);
  const snapshot = createComparisonSnapshot(input);
  const snapshotBefore = structuredClone(snapshot);
  try {
    const { killerMoves, ...quiescence } = setting;
    const options = { moveOrdering: 'standard', quiescence,
      ...(killerMoves === undefined ? {} : { killerMoves }) } as const;
    const search = mode === 'fixed'
      ? (dependencies.fixedSearch ?? analyzeAlphaBetaSearch)(snapshot, 3, undefined, dependencies.clock, options)
      : (dependencies.timedSearch ?? analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch)(snapshot, timedOptions.maxDepth,
        timedOptions.timeLimitMilliseconds, undefined, dependencies.clock, options);
    capture?.(search);
    return { setting, search, pv: validateOrderingResult(snapshot, search, mode, setting.maxTacticalDepth, timedOptions) };
  } finally {
    assert.deepStrictEqual(snapshot, snapshotBefore, '探索スナップショットが変更されました');
    assert.deepStrictEqual(input, before, '入力局面が変更されました');
  }
}

/** A four-setting case is atomic; failed cases retain context but no aggregates. */
export function runOrderingCase(position: BenchmarkPosition, mode: BenchmarkMode, dependencies: BenchmarkDependencies = {}): OrderingCase {
  let stage = '局面生成';
  try {
    const input = position.create();
    const before = structuredClone(input);
    const results: OrderingResult[] = [];
    try {
      for (const setting of ORDERING_SETTINGS) {
        stage = `追加${setting.maxTacticalDepth}手 ordering=${setting.moveOrdering}`;
        results.push(runOrderingTrial(input, mode, setting, dependencies));
      }
      if (mode === 'fixed') for (const i of [0, 2]) {
        stage = `追加${results[i].setting.maxTacticalDepth}手 original→material 評価一致`;
        assert.equal(results[i].search.selectedEvaluation, results[i + 1].search.selectedEvaluation, '固定深さ評価が一致しません');
      }
      return { position, mode, ok: true, turn: input.turn, results };
    } finally {
      assert.deepStrictEqual(input, before, '入力局面が変更されました');
    }
  } catch (error) {
    return { position, mode, ok: false, error: `position=${position.id} mode=${mode} ${stage}: ${error instanceof Error ? error.message : String(error)}` };
  }
}

export function runOrderingSuite(modes: readonly BenchmarkMode[], dependencies: BenchmarkDependencies = {},
  positions = QUIESCENCE_BENCHMARK_POSITIONS, onCase?: (entry: OrderingCase) => void): OrderingCase[] {
  assert.equal(new Set(positions.map(p => p.id)).size, positions.length, '局面ID重複');
  const cases: OrderingCase[] = [];
  for (const mode of modes) for (const position of positions) {
    const entry = runOrderingCase(position, mode, dependencies);
    cases.push(entry);
    onCase?.(entry);
  }
  return cases;
}

const evaluation = (entry: OrderingResult, turn: BoardState['turn']) => formatSenteEvaluation(entry.search.selectedEvaluation ?? entry.search.evaluationBreakdown?.total ?? null, turn);
export function formatOrderingCase(entry: OrderingCase): string {
  const lines = [`\n## ${entry.mode} / ${entry.position.id} / ${entry.position.name}`];
  if (!entry.ok) return [...lines, `ERROR: ${entry.error}`].join('\n');
  const turn = entry.turn;
  for (const r of entry.results) {
    const s = r.search;
    lines.push(`追加${r.setting.maxTacticalDepth}手 ${r.setting.moveOrdering}: 推奨手=${r.pv[0] ?? '手なし'}; 先手評価=${evaluation(r, turn)}; PV=${'resultSource' in s && s.resultSource === 'fallback' ? '未探索' : r.pv.join(' ') || '手順なし'}; 完了深さ=${s.depth}; 参考時間=${s.elapsedMilliseconds.toFixed(1)}ms`,
      `  最深完了: ${formatCounts(counts(s))}`);
    if ('iterations' in s) lines.push(`  採用反復=${s.completedDepth}/${s.requestedMaxDepth}; 完了反復=[${s.iterations.map(p => p.depth)}]; 時間切れ=${s.timedOut}; 全完了合計: ${formatCounts(counts(s, true))}`);
  }
  for (const i of [0, 2]) {
    const a = entry.results[i], b = entry.results[i + 1];
    lines.push(`追加${a.setting.maxTacticalDepth}手 original→material: 推奨手=${a.pv[0] ?? '手なし'}→${b.pv[0] ?? '手なし'}; 評価=${evaluation(a, turn)}→${evaluation(b, turn)}; 完了深さ=${a.search.depth}→${b.search.depth}; PV=${'resultSource' in a.search && a.search.resultSource === 'fallback' ? '未探索' : a.pv.join(' ') || '手順なし'} → ${'resultSource' in b.search && b.search.resultSource === 'fallback' ? '未探索' : b.pv.join(' ') || '手順なし'}`);
  }
  return lines.join('\n');
}

export function summarizeOrdering(cases: readonly OrderingCase[], mode: BenchmarkMode) {
  const entries = cases.filter(c => c.mode === mode);
  const success = entries.filter(c => c.ok);
  return { mode, success: success.length, errors: entries.length - success.length,
    settings: ORDERING_SETTINGS.map((setting, i) => ({ setting,
      depths: success.map(c => `${c.position.id}:${c.results[i].search.depth}`),
      elapsed: success.reduce((sum, c) => sum + c.results[i].search.elapsedMilliseconds, 0),
      deepest: success.reduce((sum, c) => counts(c.results[i].search).map((v, j) => sum[j] + v), Array<number>(7).fill(0)),
      totals: success.reduce((sum, c) => counts(c.results[i].search, true).map((v, j) => sum[j] + v), Array<number>(7).fill(0)),
    })),
  };
}
export function formatOrderingSummary(cases: readonly OrderingCase[], mode: BenchmarkMode): string {
  const s = summarizeOrdering(cases, mode);
  return [`\n## ${mode} 集計: 成功=${s.success}局面/${s.success * 4}設定; エラー=${s.errors}局面（4設定一組で集計）`,
    ...s.settings.flatMap(r => [`追加${r.setting.maxTacticalDepth}手 ${r.setting.moveOrdering}: 深さ=${r.depths.join(',')}; 参考時間合計=${r.elapsed.toFixed(1)}ms`,
      `  最深完了合計: ${formatCounts(r.deepest)}`, `  全完了合計: ${formatCounts(r.totals)}`]),
  ].join('\n');
}

import assert from 'node:assert/strict';
import { isDeepStrictEqual } from 'node:util';
import { createPositionKey } from '../../src/domain/shogi/repetition';
import type { LegalAction } from '../../src/domain/shogi/legalActions';
import type { BoardState } from '../../src/types/shogi';
import { QUIESCENCE_ORDERING_SELF_PLAY_SCENARIOS, type SelfPlayScenario } from './quiescenceOrderingSelfPlayScenarios';
import { WARMUP_COUNT, MEASUREMENT_COUNT, alternatingPairOrder, describeNumbers, rawJson,
  type RepeatedDependencies } from './quiescenceOrderingRepeated';
import { DEFAULT_TIMED_SEARCH_OPTIONS, runOrderingTrial, type OrderingResult, type SearchResult, type Setting,
  type TimedSearchOptions } from './quiescenceOrderingSuite';
import type { BenchmarkMode } from './quiescenceSuite';

export type ComparisonSide = 'baseline' | 'candidate';
type ComparisonPhase = 'warmup' | 'measurement';
type MetricName = 'completedDepth' | 'searchPositionCount' | 'cutoffCount' | 'skippedActionCount' | 'elapsedMilliseconds';

export interface NamedSearchSetting {
  readonly id: string;
  readonly setting: Setting;
}

/** This is a measurement/reporting configuration, not a strength judgement. */
export const SUITE_COMPARISON_CONFIG = Object.freeze({
  warmupCount: WARMUP_COUNT,
  measurementCount: MEASUREMENT_COUNT,
  execution: 'synchronous-serial-alternating-pairs',
  baseline: Object.freeze({ id: 'original', setting: Object.freeze({ maxTacticalDepth: 1, moveOrdering: 'original' }) }),
  candidate: Object.freeze({ id: 'material', setting: Object.freeze({ maxTacticalDepth: 1, moveOrdering: 'material' }) }),
} as const);

/** Same suite and all other search settings; only killer history differs. */
export const KILLER_MOVE_SUITE_COMPARISON_CONFIG = Object.freeze({
  warmupCount: WARMUP_COUNT,
  measurementCount: MEASUREMENT_COUNT,
  execution: 'synchronous-serial-alternating-pairs',
  baseline: Object.freeze({ id: 'killer-off', setting: Object.freeze({ maxTacticalDepth: 1, moveOrdering: 'original', killerMoves: false }) }),
  candidate: Object.freeze({ id: 'killer-on', setting: Object.freeze({ maxTacticalDepth: 1, moveOrdering: 'original', killerMoves: true }) }),
} as const);

export interface SuiteComparisonConfig {
  readonly mode: BenchmarkMode;
  readonly timeLimitMilliseconds: number;
  readonly maxDepth: number;
  readonly baseline: NamedSearchSetting;
  readonly candidate: NamedSearchSetting;
}

export interface SuiteComparisonTrial {
  readonly phase: ComparisonPhase;
  readonly trial: number;
  readonly order: readonly ComparisonSide[];
  readonly orderIndex: number;
  readonly side: ComparisonSide;
  ok: boolean;
  search?: SearchResult;
  pv?: string[];
  error?: string;
}

export interface SideMetrics {
  readonly completedDepth: number | null;
  /** Timed mode uses all completed iterations; fixed mode uses its sole pass. */
  readonly searchPositionCount: number | null;
  readonly cutoffCount: number | null;
  readonly skippedActionCount: number | null;
  readonly elapsedMilliseconds: number | null;
}

export interface SideObservationSummary extends SideMetrics {
  readonly sampleCount: number;
  /** The first retained measurement identifies a concrete move; all samples remain in trials. */
  readonly selectedAction: LegalAction | null;
  readonly selectedActionLabel: string;
  readonly selectedEvaluation: number | null;
  readonly selectedActionFrequencies: Array<{ readonly label: string; readonly count: number }>;
  readonly timedOutCount: number;
  readonly completedCount: number;
  readonly timeoutUnavailableCount: number;
  /** Measurement-only, valid completed depths in ascending numeric order. */
  readonly completedDepthDistribution: Array<{ readonly depth: number; readonly count: number }>;
}

export interface MetricDifference {
  readonly baseline: number | null;
  readonly candidate: number | null;
  readonly difference: number | null;
  /** null means unavailable, including a zero baseline. */
  readonly percentChange: number | null;
}

export interface PositionComparison {
  readonly scenarioId: string;
  readonly scenarioName: string;
  readonly provenance: string;
  readonly phase: SelfPlayScenario['phase'];
  readonly sideToMove: SelfPlayScenario['sideToMove'];
  readonly executionOrder: number;
  readonly mode: BenchmarkMode;
  readonly initialPositionKey?: string;
  readonly trials: SuiteComparisonTrial[];
  readonly ok: boolean;
  readonly baseline?: SideObservationSummary;
  readonly candidate?: SideObservationSummary;
  readonly selectedActionMatches?: boolean;
  readonly evaluation: MetricDifference;
  readonly metrics: Readonly<Record<MetricName, MetricDifference>>;
  readonly error?: string;
}

export interface SuiteComparisonResult {
  readonly config: SuiteComparisonConfig;
  readonly positions: PositionComparison[];
  readonly summary: {
    readonly targetPositionCount: number;
    readonly completedPositionCount: number;
    readonly errorCount: number;
    readonly selectedActionChangedPositionCount: number;
    readonly metrics: Readonly<Record<MetricName, MetricDifference>>;
  };
}

/** A narrow seam lets tests control measurements without changing the search engine. */
export type SuiteComparisonTrialRunner = (input: BoardState, mode: BenchmarkMode, setting: Setting,
  dependencies: RepeatedDependencies, capture?: (search: SearchResult) => void,
  timedOptions?: TimedSearchOptions) => OrderingResult;
export interface SuiteComparisonDependencies extends RepeatedDependencies {
  readonly trialRunner?: SuiteComparisonTrialRunner;
}

const metricNames: readonly MetricName[] = ['completedDepth', 'searchPositionCount', 'cutoffCount', 'skippedActionCount', 'elapsedMilliseconds'];
const message = (error: unknown) => error instanceof Error ? error.message : String(error);

function finite(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

function metricValue(search: SearchResult, metric: MetricName): number | null {
  switch (metric) {
    case 'completedDepth': return finite(search.depth);
    case 'elapsedMilliseconds': return finite(search.elapsedMilliseconds);
    case 'searchPositionCount':
      return finite('iterations' in search ? search.totalVisitedPositionCount : search.visitedPositionCount);
    case 'cutoffCount':
      return finite('iterations' in search ? search.totalCutoffCount : search.cutoffCount);
    case 'skippedActionCount':
      return finite('iterations' in search ? search.totalSkippedActionCount : search.skippedActionCount);
  }
}

function safeDifference(baseline: number | null, candidate: number | null): MetricDifference {
  const difference = baseline === null || candidate === null || !Number.isFinite(baseline) || !Number.isFinite(candidate)
    ? null : candidate - baseline;
  return { baseline, candidate, difference,
    percentChange: baseline === null || candidate === null || !Number.isFinite(baseline) || !Number.isFinite(candidate) || baseline === 0
      ? null : (candidate - baseline) / baseline * 100 };
}

function searchTimedOut(search: SearchResult): boolean | null {
  return 'timedOut' in search ? search.timedOut : false;
}

function completedDepthDistribution(measurements: readonly SuiteComparisonTrial[]): Array<{ readonly depth: number; readonly count: number }> {
  const counts = new Map<number, number>();
  for (const trial of measurements) {
    const depth = trial.search ? finite(trial.search.depth) : null;
    // Failed/null/non-integral observations are intentionally not recoded.
    if (depth === null || !Number.isSafeInteger(depth) || depth < 1) continue;
    counts.set(depth, (counts.get(depth) ?? 0) + 1);
  }
  return [...counts.entries()].sort(([left], [right]) => left - right)
    .map(([depth, count]) => ({ depth, count }));
}

function summarizeSide(trials: readonly SuiteComparisonTrial[], side: ComparisonSide): SideObservationSummary {
  const measurements = trials.filter((trial) => trial.phase === 'measurement' && trial.side === side);
  assert.equal(measurements.length, MEASUREMENT_COUNT, `${side} measurement count`);
  assert.ok(measurements.every((trial) => trial.ok && trial.search), `${side} has an incomplete measurement`);
  const first = measurements[0];
  const values = (metric: MetricName) => measurements.map((trial) => metricValue(trial.search!, metric));
  const median = (metric: MetricName) => {
    const samples = values(metric);
    return samples.every((value): value is number => value !== null) ? describeNumbers(samples).median : null;
  };
  const frequencies = new Map<string, { label: string; count: number }>();
  for (const trial of measurements) {
    const label = trial.pv?.[0] ?? '手なし';
    const key = rawJson(trial.search!.selectedAction);
    const item = frequencies.get(key) ?? { label, count: 0 };
    item.count++;
    frequencies.set(key, item);
  }
  const timeoutValues = measurements.map((trial) => searchTimedOut(trial.search!));
  return {
    sampleCount: measurements.length,
    selectedAction: first.search!.selectedAction,
    selectedActionLabel: first.pv?.[0] ?? '手なし',
    selectedEvaluation: first.search!.selectedEvaluation,
    selectedActionFrequencies: [...frequencies.values()],
    timedOutCount: timeoutValues.filter((value) => value === true).length,
    completedCount: timeoutValues.filter((value) => value === false).length,
    timeoutUnavailableCount: timeoutValues.filter((value) => value === null).length,
    completedDepthDistribution: completedDepthDistribution(measurements),
    completedDepth: median('completedDepth'), searchPositionCount: median('searchPositionCount'),
    cutoffCount: median('cutoffCount'), skippedActionCount: median('skippedActionCount'),
    elapsedMilliseconds: median('elapsedMilliseconds'),
  };
}

function emptyDifference(): MetricDifference {
  return safeDifference(null, null);
}

function failedPosition(scenario: SelfPlayScenario, executionOrder: number, mode: BenchmarkMode,
  trials: SuiteComparisonTrial[], error: string, initialPositionKey?: string): PositionComparison {
  return { scenarioId: scenario.id, scenarioName: scenario.name, provenance: scenario.provenance,
    phase: scenario.phase, sideToMove: scenario.sideToMove,
    executionOrder, mode, initialPositionKey, trials, ok: false, error,
    evaluation: emptyDifference(), metrics: Object.fromEntries(metricNames.map((metric) => [metric, emptyDifference()])) as Record<MetricName, MetricDifference> };
}

function runPositionComparison(scenario: SelfPlayScenario, executionOrder: number, config: SuiteComparisonConfig,
  dependencies: SuiteComparisonDependencies): PositionComparison {
  const trials: SuiteComparisonTrial[] = [];
  let initialPositionKey: string | undefined;
  let stage = 'setup';
  try {
    const input = scenario.create();
    const inputBefore = structuredClone(input);
    initialPositionKey = createPositionKey(input);
    const runner = dependencies.trialRunner ?? runOrderingTrial;
    for (const phase of ['warmup', 'measurement'] as const) {
      const count = phase === 'warmup' ? WARMUP_COUNT : MEASUREMENT_COUNT;
      for (let index = 0; index < count; index++) {
        const order = alternatingPairOrder('baseline', 'candidate', executionOrder - 1 + index);
        for (const [orderIndex, side] of order.entries()) {
          const setting = config[side].setting;
          stage = `phase=${phase} trial=${index + 1} side=${side}`;
          const trial: SuiteComparisonTrial = { phase, trial: index + 1, order, orderIndex, side, ok: false };
          trials.push(trial);
          try {
            // runOrderingTrial invokes capture before result validation. Retain an
            // independent raw snapshot even when that validation then throws.
            const result = runner(input, config.mode, setting, dependencies, search => {
              trial.search = structuredClone(search);
            }, { timeLimitMilliseconds: config.timeLimitMilliseconds, maxDepth: config.maxDepth });
            const returnedSearch = structuredClone(result.search);
            assert.ok(trial.search === undefined || isDeepStrictEqual(trial.search, returnedSearch),
              'capture結果と正常終了結果の検索データが一致しません');
            trial.search = returnedSearch;
            trial.pv = [...result.pv];
            trial.ok = true;
          } catch (error) {
            trial.error = `${stage}: ${message(error)}`;
            throw error;
          }
        }
      }
    }
    assert.deepStrictEqual(input, inputBefore, '入力局面が変更されました');
    const baseline = summarizeSide(trials, 'baseline');
    const candidate = summarizeSide(trials, 'candidate');
    const metrics = Object.fromEntries(metricNames.map((metric) => [metric,
      safeDifference(baseline[metric], candidate[metric])])) as Record<MetricName, MetricDifference>;
    return { scenarioId: scenario.id, scenarioName: scenario.name, provenance: scenario.provenance,
      phase: scenario.phase, sideToMove: scenario.sideToMove,
      executionOrder, mode: config.mode, initialPositionKey, trials, ok: true, baseline, candidate,
      selectedActionMatches: isDeepStrictEqual(baseline.selectedAction, candidate.selectedAction),
      evaluation: safeDifference(finite(baseline.selectedEvaluation), finite(candidate.selectedEvaluation)), metrics };
  } catch (error) {
    return failedPosition(scenario, executionOrder, config.mode, trials,
      `scenario=${scenario.id} ${stage}: ${message(error)}`, initialPositionKey);
  }
}

function aggregateMetric(positions: readonly PositionComparison[], metric: MetricName): MetricDifference {
  // A suite with no completed position still has a useful structured failure
  // report. There is no representative numeric value for any metric.
  if (positions.length === 0) return emptyDifference();
  const baseline = positions.map((position) => position.baseline![metric]);
  const candidate = positions.map((position) => position.candidate![metric]);
  if (!baseline.every((value): value is number => value !== null) || !candidate.every((value): value is number => value !== null)) return emptyDifference();
  const aggregate = metric === 'searchPositionCount' || metric === 'cutoffCount' || metric === 'skippedActionCount'
    ? (values: readonly number[]) => values.reduce((sum, value) => sum + value, 0)
    : (values: readonly number[]) => describeNumbers(values).median;
  return safeDifference(aggregate(baseline), aggregate(candidate));
}

function validateConfig(config: SuiteComparisonConfig): void {
  assert.ok(config.mode === 'fixed' || config.mode === 'timed', 'Comparison mode must be fixed or timed.');
  assert.ok(Number.isSafeInteger(config.timeLimitMilliseconds) && config.timeLimitMilliseconds > 0,
    'Comparison timeLimitMilliseconds must be a positive integer.');
  assert.ok(Number.isSafeInteger(config.maxDepth) && config.maxDepth >= 1,
    'Comparison maxDepth must be an integer of at least 1.');
  assert.ok(config.baseline.id.length > 0 && config.candidate.id.length > 0, 'Comparison setting IDs are required.');
  assert.notEqual(config.baseline.id, config.candidate.id, 'Baseline and candidate IDs must differ.');
  for (const [side, named] of Object.entries({ baseline: config.baseline, candidate: config.candidate }) as
    Array<[ComparisonSide, NamedSearchSetting]>) {
    assert.ok(named.setting.maxTacticalDepth === 1 || named.setting.maxTacticalDepth === 2,
      `${side} tactical depth must be 1 or 2.`);
    assert.ok(named.setting.moveOrdering === 'original' || named.setting.moveOrdering === 'material',
      `${side} move ordering must be original or material.`);
    assert.ok(named.setting.killerMoves === undefined || typeof named.setting.killerMoves === 'boolean',
      `${side} killerMoves must be boolean when provided.`);
  }
}

/** Runs the PR #136 scenario catalogue without duplicating the existing search executor. */
export function runSuiteComparison(config: SuiteComparisonConfig,
  dependencies: SuiteComparisonDependencies = {}, scenarios: readonly SelfPlayScenario[] = QUIESCENCE_ORDERING_SELF_PLAY_SCENARIOS): SuiteComparisonResult {
  validateConfig(config);
  assert.equal(new Set(scenarios.map((scenario) => scenario.id)).size, scenarios.length, 'Scenario IDs must be unique.');
  const positions = scenarios.map((scenario, index) => runPositionComparison(scenario, index + 1, config, dependencies));
  const completed = positions.filter((position) => position.ok);
  return { config, positions, summary: {
    targetPositionCount: positions.length,
    completedPositionCount: completed.length,
    errorCount: positions.length - completed.length,
    selectedActionChangedPositionCount: completed.filter((position) => position.selectedActionMatches === false).length,
    metrics: Object.fromEntries(metricNames.map((metric) => [metric, aggregateMetric(completed, metric)])) as Record<MetricName, MetricDifference>,
  } };
}

export function defaultSuiteComparisonConfig(mode: BenchmarkMode = 'timed'): SuiteComparisonConfig {
  return { mode, ...DEFAULT_TIMED_SEARCH_OPTIONS, baseline: SUITE_COMPARISON_CONFIG.baseline, candidate: SUITE_COMPARISON_CONFIG.candidate };
}

export function defaultKillerMoveSuiteComparisonConfig(mode: BenchmarkMode = 'timed'): SuiteComparisonConfig {
  return { mode, ...DEFAULT_TIMED_SEARCH_OPTIONS, baseline: KILLER_MOVE_SUITE_COMPARISON_CONFIG.baseline,
    candidate: KILLER_MOVE_SUITE_COMPARISON_CONFIG.candidate };
}

export function parseSuiteComparisonMode(args: readonly string[]): BenchmarkMode {
  if (args.length === 0) return 'timed';
  if (args.length === 1 && (args[0] === 'fixed' || args[0] === 'timed')) return args[0];
  throw new Error('Usage: npm run measure:quiescence-ordering-suite-comparison -- [fixed|timed]');
}

const value = (metric: MetricDifference) => metric.difference === null
  ? '未算出' : `${metric.baseline}→${metric.candidate} (差=${metric.difference}, 率=${metric.percentChange === null ? '未算出' : `${metric.percentChange}%`})`;
const describeSetting = (named: NamedSearchSetting) => `${named.id}=${rawJson(named.setting)}`;
const describeDepthDistribution = (distribution: readonly { readonly depth: number; readonly count: number }[]) =>
  distribution.length === 0 ? 'なし' : distribution.map(({ depth, count }) => `depth ${depth}×${count}`).join('、');

/** Human-facing rendering deliberately reports measurements only; it never names a winner. */
export function formatSuiteComparison(result: SuiteComparisonResult): string {
  const summary = result.summary;
  const lines = [
    'A/B 探索設定スイート比較',
    `mode=${result.config.mode}; timeLimitMilliseconds=${result.config.timeLimitMilliseconds}; maxDepth=${result.config.maxDepth}`,
    `baseline設定=${describeSetting(result.config.baseline)}; candidate設定=${describeSetting(result.config.candidate)}`,
    `対象局面=${summary.targetPositionCount}; 正常完了=${summary.completedPositionCount}; エラー=${summary.errorCount}; 選択手変更=${summary.selectedActionChangedPositionCount}`,
    `到達深さ（局面中央値の中央値）: ${value(summary.metrics.completedDepth)}`,
    `探索局面数（局面中央値の合計）: ${value(summary.metrics.searchPositionCount)}`,
    `カットオフ数（局面中央値の合計）: ${value(summary.metrics.cutoffCount)}`,
    `スキップ手数（局面中央値の合計）: ${value(summary.metrics.skippedActionCount)}`,
    `経過時間ms（局面中央値の中央値）: ${value(summary.metrics.elapsedMilliseconds)}`,
    '局面別の本測定:',
  ];
  if (result.positions.length === 0) lines.push('  該当なし');
  for (const position of result.positions) {
    if (!position.ok) {
      lines.push(`  ${position.scenarioId}: phase=${position.phase}; sideToMove=${position.sideToMove}; ERROR ${position.error}`);
      continue;
    }
    lines.push(`  ${position.scenarioId}: phase=${position.phase}; sideToMove=${position.sideToMove}; 手=${position.baseline!.selectedActionLabel}→${position.candidate!.selectedActionLabel}; 評価=${position.baseline!.selectedEvaluation}→${position.candidate!.selectedEvaluation}; 完了深さ中央値=${position.baseline!.completedDepth}→${position.candidate!.completedDepth}; 深さ分布=${describeDepthDistribution(position.baseline!.completedDepthDistribution)}→${describeDepthDistribution(position.candidate!.completedDepthDistribution)}; 探索局面数=${position.baseline!.searchPositionCount}→${position.candidate!.searchPositionCount}; cutoff=${position.baseline!.cutoffCount}→${position.candidate!.cutoffCount}; skip=${position.baseline!.skippedActionCount}→${position.candidate!.skippedActionCount}; 経過時間ms=${position.baseline!.elapsedMilliseconds}→${position.candidate!.elapsedMilliseconds}; timeout=${position.baseline!.timedOutCount}→${position.candidate!.timedOutCount}`);
  }
  return lines.join('\n');
}

/** JSON.stringify-compatible without silently turning Infinity into null. */
export const serializeSuiteComparison = (result: SuiteComparisonResult): string => rawJson(result);

export function runSuiteComparisonCli(args: readonly string[], dependencies: SuiteComparisonDependencies = {},
  scenarios = QUIESCENCE_ORDERING_SELF_PLAY_SCENARIOS, write: (line: string) => void = console.log,
  configForMode: (mode: BenchmarkMode) => SuiteComparisonConfig = defaultSuiteComparisonConfig): 0 | 1 {
  try {
    const result = runSuiteComparison(configForMode(parseSuiteComparisonMode(args)), dependencies, scenarios);
    write(formatSuiteComparison(result));
    write(`JSON ${serializeSuiteComparison(result)}`);
    return result.summary.errorCount === 0 ? 0 : 1;
  } catch (error) {
    write(`ERROR ${message(error)}`);
    return 1;
  }
}

export interface KillerMoveSuiteComparisonCliArguments {
  readonly mode: BenchmarkMode;
  readonly timeLimitMilliseconds: number;
  readonly maxDepth: number;
}

const killerMoveCliUsage = 'Usage: npm run measure:killer-move-suite-comparison -- [fixed|timed] [--time-limit-ms <positive integer>] [--max-depth <integer >= 1>]';

function parsePositiveInteger(option: string, raw: string | undefined, minimum: number): number {
  if (raw === undefined || raw.startsWith('--') || !/^(?:0|[1-9]\d*)$/.test(raw)) {
    throw new Error(`${option} must be an integer${minimum === 1 ? ' of at least 1' : ' greater than 0'}. ${killerMoveCliUsage}`);
  }
  const parsed = Number(raw);
  if (!Number.isSafeInteger(parsed) || parsed < minimum) {
    throw new Error(`${option} must be an integer${minimum === 1 ? ' of at least 1' : ' greater than 0'}. ${killerMoveCliUsage}`);
  }
  return parsed;
}

/** Parses the killer-only timed options without altering the established mode parser. */
export function parseKillerMoveSuiteComparisonCliArguments(args: readonly string[]): KillerMoveSuiteComparisonCliArguments {
  let mode: BenchmarkMode = 'timed';
  let explicitMode = false;
  let timeLimitMilliseconds = DEFAULT_TIMED_SEARCH_OPTIONS.timeLimitMilliseconds;
  let maxDepth = DEFAULT_TIMED_SEARCH_OPTIONS.maxDepth;
  let sawTimedOption = false;
  for (let index = 0; index < args.length; index++) {
    const argument = args[index];
    if (argument === 'fixed' || argument === 'timed') {
      if (explicitMode) throw new Error(`Mode may be specified only once. ${killerMoveCliUsage}`);
      mode = argument;
      explicitMode = true;
      continue;
    }
    if (argument === '--time-limit-ms') {
      if (sawTimedOption && args.slice(0, index).includes('--time-limit-ms')) throw new Error(`--time-limit-ms may be specified only once. ${killerMoveCliUsage}`);
      timeLimitMilliseconds = parsePositiveInteger(argument, args[++index], 1);
      sawTimedOption = true;
      continue;
    }
    if (argument === '--max-depth') {
      if (args.slice(0, index).includes('--max-depth')) throw new Error(`--max-depth may be specified only once. ${killerMoveCliUsage}`);
      maxDepth = parsePositiveInteger(argument, args[++index], 1);
      sawTimedOption = true;
      continue;
    }
    throw new Error(`Unknown argument: ${argument}. ${killerMoveCliUsage}`);
  }
  if (mode === 'fixed' && sawTimedOption) throw new Error(`Timed-only options cannot be used with fixed mode. ${killerMoveCliUsage}`);
  return { mode, timeLimitMilliseconds, maxDepth };
}

/** Killer CLI extension; the shared comparison CLI deliberately keeps its legacy grammar. */
export function runKillerMoveSuiteComparisonCli(args: readonly string[], dependencies: SuiteComparisonDependencies = {},
  scenarios = QUIESCENCE_ORDERING_SELF_PLAY_SCENARIOS, write: (line: string) => void = console.log,
  configForMode: (mode: BenchmarkMode) => SuiteComparisonConfig = defaultKillerMoveSuiteComparisonConfig): 0 | 1 {
  try {
    const parsed = parseKillerMoveSuiteComparisonCliArguments(args);
    const base = configForMode(parsed.mode);
    const result = runSuiteComparison({ ...base, timeLimitMilliseconds: parsed.timeLimitMilliseconds, maxDepth: parsed.maxDepth }, dependencies, scenarios);
    write(formatSuiteComparison(result));
    write(`JSON ${serializeSuiteComparison(result)}`);
    return result.summary.errorCount === 0 ? 0 : 1;
  } catch (error) {
    write(`ERROR ${message(error)}`);
    return 1;
  }
}

