import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { createInitialBoardState, type BoardState } from '../../src/types/shogi';
import { executeLegalAction, getLegalActions } from '../../src/domain/shogi/legalActions';
import { createPositionKey } from '../../src/domain/shogi/repetition';
import { areLegalActionsEqual } from '../../src/domain/shogi/twoPlyAlphaBetaAi';
import type { MeasurementGame } from './timedFallbackSelfPlay';

export const SOURCE = 'docs/benchmarks/timed-fallback-100ms-20260924.jsonl';
export const POSITION_IDS = [
  { game: 1, ply: 5, band: 'opening' },
  { game: 1, ply: 30, band: 'opening' },
  { game: 2, ply: 54, band: 'middle' },
  { game: 3, ply: 55, band: 'middle' },
  { game: 4, ply: 89, band: 'late' },
  { game: 2, ply: 92, band: 'late' },
  { game: 1, ply: 115, band: 'late' },
] as const;

export function replayPositions(source = SOURCE, requested: readonly { game: number; ply: number; band: string }[] = POSITION_IDS) {
  const bytes = readFileSync(source);
  const rows = bytes.toString('utf8').trim().split(/\r?\n/).map(line => JSON.parse(line));
  const games = rows.filter(row => row.type === 'game') as MeasurementGame[];
  const positions = [] as Array<{ id: string; band: string; state: BoardState; sourceResult: string;
    sourceActualMilliseconds: number; stateSha256: string; positionKeySha256: string; historyLength: number }>;
  for (const item of requested) {
    const game = games[item.game - 1];
    assert.equal(game.executionIndex, item.game);
    let state = createInitialBoardState();
    for (const ply of game.plies) {
      assert.equal(ply.positionKey, createPositionKey(state));
      if (ply.ply === item.ply) {
        assert.equal(state.history.length, item.ply - 1);
        positions.push({ id: `g${item.game}-p${item.ply}`, band: item.band, state,
          sourceResult: ply.resultSource, sourceActualMilliseconds: ply.actualElapsedMilliseconds,
          stateSha256: createHash('sha256').update(JSON.stringify({ ...state, recordId: 'replayed' })).digest('hex'),
          positionKeySha256: createHash('sha256').update(ply.positionKey).digest('hex'),
          historyLength: state.history.length });
        break;
      }
      assert.ok(getLegalActions(state).some(action => areLegalActionsEqual(action, ply.action)));
      const next = executeLegalAction(state, ply.action, { proposer: 'local_ai' });
      assert.equal(next.type, 'applied');
      if (next.type === 'applied') state = next.state;
    }
  }
  assert.equal(positions.length, requested.length);
  return { positions, sourceSha256: createHash('sha256').update(bytes).digest('hex') };
}

export type Sample = {
  type: 'sample'; positionId: string; band: string; mode: 'timed' | 'fixed';
  probe: boolean; phase: 'warmup' | 'measurement'; run: number;
  actualElapsedMilliseconds: number; apiElapsedMilliseconds: number;
  completedDepth: number; resultSource: string; timedOut: boolean;
  action: unknown; evaluation: number | null; pv: unknown;
  diagnostics: null | { phases: unknown; apiOtherMilliseconds: number; totalMilliseconds: number;
    crossedDeadlinePhase: string | null; interruptedPhase: string | null };
};

const median = (values: number[]) => {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted.length ? sorted[Math.ceil(sorted.length / 2) - 1] : null;
};

export function summarizeSamples(samples: Sample[]) {
  const rows = samples.filter(s => s.phase === 'measurement');
  return ['opening', 'middle', 'late'].flatMap(band =>
    (['timed', 'fixed'] as const).flatMap(mode => [false, true].map(probe => {
      const own = rows.filter(s => s.band === band && s.mode === mode && s.probe === probe);
      const phaseNames = ['root-legal', 'normal-legal', 'normal-order', 'see', 'normal-execute', 'normal-other', 'quiescence'] as const;
      return { band, mode, probe, samples: own.length, positions: [...new Set(own.map(s => s.positionId))],
        depthOneCompletion: own.filter(s => s.completedDepth >= 1).length,
        fallback: own.filter(s => s.resultSource === 'fallback').length,
        actualMedianMilliseconds: median(own.map(s => s.actualElapsedMilliseconds)),
        actualMaxMilliseconds: Math.max(0, ...own.map(s => s.actualElapsedMilliseconds)),
        over100Count: own.filter(s => s.actualElapsedMilliseconds > 100).length,
        over105Count: own.filter(s => s.actualElapsedMilliseconds > 105).length,
        crossedDeadlinePhases: Object.fromEntries([...new Set(own.map(s => s.diagnostics?.crossedDeadlinePhase).filter(Boolean))]
          .map(phase => [phase, own.filter(s => s.diagnostics?.crossedDeadlinePhase === phase).length])),
        interruptedPhases: Object.fromEntries([...new Set(own.map(s => s.diagnostics?.interruptedPhase).filter(Boolean))]
          .map(phase => [phase, own.filter(s => s.diagnostics?.interruptedPhase === phase).length])),
        phaseMedianMilliseconds: probe ? Object.fromEntries(phaseNames.map(name => [name, median(own.map(s =>
          (s.diagnostics!.phases as Record<string, { milliseconds: number }>)[name].milliseconds))])) : null,
        apiOtherMedianMilliseconds: probe ? median(own.map(s => s.diagnostics!.apiOtherMilliseconds)) : null,
      };
    })));
}

scripts/benchmarks/timedFallbackSelfPlay:
import { performance } from 'node:perf_hooks';
import type { BoardState } from '../../src/types/shogi';
import { createInitialBoardState } from '../../src/types/shogi';
import { runPairedSelfPlayMatch, type PairedSelfPlayOutcome, type PairedSelfPlayParticipantId } from '../../src/domain/shogi/pairedSelfPlayMatch';
import type { SelfPlayParticipant, SelfPlayPlyRecord } from '../../src/domain/shogi/selfPlayGame';
import { resolveSearchEvaluationPreset } from '../../src/domain/shogi/searchEvaluationPresets';
import { analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch } from '../../src/domain/shogi/twoPlyAlphaBetaAi';
import { SearchDiagnostics } from '../../src/domain/shogi/searchDiagnostics';

export interface MeasurementConfig {
  pairCount: number;
  maxPlies: number;
  timeLimitMilliseconds: number;
  maxDepth: number;
  evaluationPreset: 'standard';
  moveOrdering: 'standard';
  quiescenceMoveOrdering: 'original';
  maxTacticalDepth: number;
  initialPosition: 'standard-hirate';
}

export const DEFAULT_CONFIG: MeasurementConfig = {
  pairCount: 2, maxPlies: 120, timeLimitMilliseconds: 100, maxDepth: 4,
  evaluationPreset: 'standard', moveOrdering: 'standard',
  quiescenceMoveOrdering: 'original', maxTacticalDepth: 1, initialPosition: 'standard-hirate',
};

export type MeasurementPly = SelfPlayPlyRecord & {
  participant: PairedSelfPlayParticipantId;
  timeLimitMilliseconds: number;
  actualElapsedMilliseconds: number;
  resultSource: 'fallback' | 'partial-root' | 'completed-iteration' | 'no-legal-actions' | 'ended-position';
};

export interface MeasurementGame {
  type: 'game';
  pairNumber: number;
  gameNumber: 1 | 2;
  executionIndex: number;
  sente: PairedSelfPlayParticipantId;
  gote: PairedSelfPlayParticipantId;
  outcome: PairedSelfPlayOutcome;
  status: 'ended' | 'max_plies' | 'failed';
  detail: unknown;
  plies: MeasurementPly[];
}

export type Search = typeof analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch;

/** Only adds observations; rules, search, evaluation and move choice stay in existing APIs. */
export function runMeasurement(config: MeasurementConfig, options: {
  search?: Search;
  now?: () => number;
  initialState?: BoardState;
  onGame?: (game: MeasurementGame) => void;
  beforeSearch?: (position: BoardState) => unknown;
  probe?: boolean;
  onSearch?: (position: BoardState, result: ReturnType<Search>, timing: {
    startedAt: number; finishedAt: number; diagnostics: SearchDiagnostics | null; before: unknown;
  }) => void;
} = {}): MeasurementGame[] {
  if (!Number.isSafeInteger(config.pairCount) || config.pairCount < 1 ||
    !Number.isSafeInteger(config.maxPlies) || config.maxPlies < 1) {
    throw new RangeError('pairCount and maxPlies must be positive safe integers');
  }
  const search = options.search ?? analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch;
  const now = options.now ?? performance.now.bind(performance);
  const state = options.initialState ?? createInitialBoardState();
  const participant = (): SelfPlayParticipant<MeasurementConfig> => ({
    settings: { ...config },
    search: (position, settings) => {
      const before = options.beforeSearch?.(position);
      const diagnostics = options.probe ? new SearchDiagnostics() : undefined;
      const start = now();
      const result = search(position, settings.maxDepth, settings.timeLimitMilliseconds,
        resolveSearchEvaluationPreset(settings.evaluationPreset), undefined,
        { moveOrdering: settings.moveOrdering, quiescence: {
          maxTacticalDepth: settings.maxTacticalDepth, moveOrdering: settings.quiescenceMoveOrdering,
        } }, diagnostics);
      const finishedAt = now();
      const actualElapsedMilliseconds = finishedAt - start;
      if (!Number.isFinite(actualElapsedMilliseconds) || actualElapsedMilliseconds < 0) {
        throw new Error('Invalid monotonic search duration');
      }
      options.onSearch?.(position, result, { startedAt: start, finishedAt, diagnostics: diagnostics ?? null, before });
      return { ...result, actualElapsedMilliseconds };
    },
  });
  const a = participant(), b = participant();
  const games: MeasurementGame[] = [];
  for (let pairIndex = 0; pairIndex < config.pairCount; pairIndex++) {
    // AB→BA in odd pairs and BA→AB in even pairs balances first-game order.
    const swapped = pairIndex % 2 === 1;
    const result = runPairedSelfPlayMatch({ initialState: state,
      a: swapped ? b : a, b: swapped ? a : b, maxPlies: config.maxPlies });
    const globalId = (local: PairedSelfPlayParticipantId): PairedSelfPlayParticipantId =>
      swapped ? (local === 'A' ? 'B' : 'A') : local;
    for (const game of result.games) {
      const sente = globalId(game.sente), gote = globalId(game.gote);
      const outcome = swapped && (game.outcome === 'a_win' || game.outcome === 'b_win')
        ? (game.outcome === 'a_win' ? 'b_win' : 'a_win') : game.outcome;
      const plies = game.result.plies.map((ply): MeasurementPly => {
        if (ply.resultSource === undefined || ply.actualElapsedMilliseconds === undefined ||
          ply.elapsedMilliseconds === null || ply.completedDepth === null || ply.timedOut === null) {
          throw new Error('Timed search observation is incomplete');
        }
        return { ...ply, resultSource: ply.resultSource,
          actualElapsedMilliseconds: ply.actualElapsedMilliseconds,
          participant: ply.player === 'sente' ? sente : gote,
          timeLimitMilliseconds: config.timeLimitMilliseconds };
      });
      const record: MeasurementGame = {
        type: 'game', pairNumber: pairIndex + 1, gameNumber: game.gameNumber,
        executionIndex: games.length + 1, sente, gote, outcome, status: game.result.status,
        detail: game.result.status === 'ended' ? game.result.gameResult :
          game.result.status === 'failed' ? game.result.failure : { reason: 'max_plies' },
        plies,
      };
      games.push(record);
      options.onGame?.(record);
    }
  }
  return games;
}

const outcomeCounts = (games: readonly MeasurementGame[]) => ({
  aWins: games.filter(g => g.outcome === 'a_win').length,
  bWins: games.filter(g => g.outcome === 'b_win').length,
  draws: games.filter(g => g.outcome === 'draw').length,
  maxPlies: games.filter(g => g.outcome === 'max_plies').length,
  failures: games.filter(g => g.outcome === 'failed').length,
});

const percentile = (sorted: number[], fraction: number): number | null =>
  sorted.length ? sorted[Math.ceil(sorted.length * fraction) - 1] : null;

export function summarizePlies(plies: readonly MeasurementPly[]) {
  const fallback = plies.filter(p => p.resultSource === 'fallback');
  const depths: Record<string, number> = {};
  const bands: Record<string, { moves: number; fallbacks: number }> = {};
  const excess = plies.map(p => p.actualElapsedMilliseconds - p.timeLimitMilliseconds);
  const positive = excess.filter(n => n > 0).sort((a, b) => a - b);
  const excessBins = { withinLimit: 0, over0to5: 0, over5to20: 0, over20to100: 0, over100: 0 };
  for (const ply of plies) {
    if (ply.resultSource !== 'fallback' && ply.resultSource !== 'completed-iteration' && ply.resultSource !== 'partial-root') throw new Error('Missing resultSource');
    if (ply.actualElapsedMilliseconds === undefined || ply.elapsedMilliseconds === null ||
      ply.completedDepth === null || ply.timedOut === null) throw new Error('Missing timed observation');
    const depth = String(ply.completedDepth);
    depths[depth] = (depths[depth] ?? 0) + 1;
    const lower = Math.floor((ply.ply - 1) / 20) * 20 + 1;
    const band = `${lower}-${lower + 19}`;
    bands[band] ??= { moves: 0, fallbacks: 0 };
    bands[band].moves++;
    if (ply.resultSource === 'fallback') bands[band].fallbacks++;
  }
  for (const value of excess) {
    if (value <= 0) excessBins.withinLimit++;
    else if (value <= 5) excessBins.over0to5++;
    else if (value <= 20) excessBins.over5to20++;
    else if (value <= 100) excessBins.over20to100++;
    else excessBins.over100++;
  }
  return {
    moves: plies.length, fallbackCount: fallback.length,
    fallbackRate: plies.length ? fallback.length / plies.length : null,
    fallbackPlies: fallback.map(p => p.ply), fallbackByPlyBand: bands,
    completedDepthDistribution: depths,
    timedOutCount: plies.filter(p => p.timedOut).length,
    actualOverLimit: { count: positive.length, rate: plies.length ? positive.length / plies.length : null,
      medianExcessMilliseconds: percentile(positive, .5), p95ExcessMilliseconds: percentile(positive, .95),
      maxExcessMilliseconds: positive.at(-1) ?? null, distribution: excessBins },
  };
}

/** Pure re-aggregation from JSONL game rows; no search result or in-memory runner needed. */
export function summarizeGames(games: readonly MeasurementGame[]) {
  const ids = ['A', 'B'] as const;
  const participants = Object.fromEntries(ids.map(id => {
    const ownGames = games;
    const ownWin = id === 'A' ? 'a_win' : 'b_win';
    const otherWin = id === 'A' ? 'b_win' : 'a_win';
    return [id, { games: ownGames.length,
      outcomes: { wins: ownGames.filter(g => g.outcome === ownWin).length,
        losses: ownGames.filter(g => g.outcome === otherWin).length,
        draws: ownGames.filter(g => g.outcome === 'draw').length,
        maxPlies: ownGames.filter(g => g.outcome === 'max_plies').length,
        failures: ownGames.filter(g => g.outcome === 'failed').length },
      ...summarizePlies(games.flatMap(g => g.plies.filter(p => p.participant === id))) }];
  }));
  const perGame = games.map(g => ({ pairNumber: g.pairNumber, gameNumber: g.gameNumber,
    executionIndex: g.executionIndex, sente: g.sente, gote: g.gote,
    outcome: g.outcome, status: g.status, plies: g.plies.length,
    participants: Object.fromEntries(ids.map(id => [id,
      summarizePlies(g.plies.filter(p => p.participant === id))])) }));
  const byFallback = Object.fromEntries(['withFallback', 'withoutFallback'].map(kind => {
    const selected = games.filter(g => g.plies.some(p => p.resultSource === 'fallback') === (kind === 'withFallback'));
    return [kind, { games: selected.length, outcomes: outcomeCounts(selected) }];
  }));
  return { totalGames: games.length, outcomes: outcomeCounts(games),
    totalPlies: games.reduce((n, g) => n + g.plies.length, 0),
    participants, byFallback, perGame };
}

scripts/benchmarks/timedLongTail.ts:
import type { SearchDiagnostics } from '../../src/domain/shogi/searchDiagnostics';

export interface LongTailSample {
  type: 'sample'; source: 'game' | 'replay'; id: string; gameId: string | null;
  ply: number; positionKeySha256: string; historyLength: number;
  probe: boolean; phase: 'warmup' | 'measurement'; run: number;
  resultSource: 'fallback' | 'partial-root' | 'completed-iteration' | 'no-legal-actions' | 'ended-position'; completedDepth: number; timedOut: boolean;
  apiElapsedMilliseconds: number; callElapsedMilliseconds: number; excessMilliseconds: number;
  action: unknown; diagnostics: null | {
    phases: SearchDiagnostics['phases']; apiOtherMilliseconds: number; totalMilliseconds: number;
    crossedDeadlinePhase: SearchDiagnostics['crossedDeadlinePhase'];
    interruptedPhase: SearchDiagnostics['interruptedPhase'];
    longestCheckInterval: SearchDiagnostics['longestCheckInterval'];
    longestOperation: SearchDiagnostics['longestOperation'];
  };
  interval: { start: number; end: number };
  gc: { status: 'available' | 'unavailable'; reason: string | null;
    events: Array<{ start: number; duration: number; kind: number; flags: number; overlapsSearch: boolean }> };
  heap: { status: 'available' | 'unavailable'; reason: string | null;
    before: { at: number; bytes: number } | null; after: { at: number; bytes: number } | null };
}

const maxBy = <T>(rows: T[], value: (row: T) => number) =>
  rows.reduce<T | null>((best, row) => best === null || value(row) > value(best) ? row : best, null);

export function summarizeLongTail(samples: LongTailSample[]) {
  const rows = samples.filter(row => row.phase === 'measurement');
  const replay = rows.filter(row => row.source === 'replay');
  const pairs = replay.filter(row => row.probe).map(on => {
    const off = replay.find(row => !row.probe && row.id === on.id && row.run === on.run);
    if (!off) throw new Error(`Missing OFF pair: ${on.id}/${on.run}`);
    return { delta: on.callElapsedMilliseconds - off.callElapsedMilliseconds,
      actionChanged: JSON.stringify(on.action) !== JSON.stringify(off.action),
      depthChanged: on.completedDepth !== off.completedDepth };
  });
  const deltas = pairs.map(pair => pair.delta).sort((a, b) => a - b);
  const largest = maxBy(rows, row => row.excessMilliseconds);
  const checks = rows.filter(row => row.diagnostics);
  const longestCheck = maxBy(checks, row => row.diagnostics!.longestCheckInterval.milliseconds);
  const interior = checks.flatMap(row => Object.entries(row.diagnostics!.phases)
    .filter(([name]) => name.startsWith('root-') && name !== 'root-legal' || name.startsWith('q-'))
    .map(([phase, entry]) => ({ id: row.id, phase, milliseconds: entry.maxMilliseconds ?? 0, calls: entry.calls })));
  const longestInterior = maxBy(interior, row => row.milliseconds);
  const longestRootInterior = maxBy(interior.filter(row => row.phase.startsWith('root-')), row => row.milliseconds);
  const longestQuiescenceInterior = maxBy(interior.filter(row => row.phase.startsWith('q-')), row => row.milliseconds);
  return {
    samples: rows.length, games: new Set(rows.filter(row => row.source === 'game').map(row => row.gameId)).size,
    fallback: rows.filter(row => row.resultSource === 'fallback').length,
    over100: rows.filter(row => row.excessMilliseconds > 0).length,
    over105: rows.filter(row => row.excessMilliseconds > 5).length,
    maxExcess: largest && { id: largest.id, milliseconds: largest.excessMilliseconds },
    longestCheck: longestCheck && { id: longestCheck.id, ...longestCheck.diagnostics!.longestCheckInterval },
    longestInterior,
    longestRootInterior, longestQuiescenceInterior,
    gcEvents: rows.reduce((sum, row) => sum + row.gc.events.length, 0),
    gcOverlaps: rows.reduce((sum, row) => sum + row.gc.events.filter(event => event.overlapsSearch).length, 0),
    heapFirst: rows[0]?.heap.before ?? null, heapLast: rows.at(-1)?.heap.after ?? null,
    missingGc: rows.filter(row => row.gc.status === 'unavailable').length,
    missingHeap: rows.filter(row => row.heap.status === 'unavailable').length,
    probePairs: { count: pairs.length, medianDeltaMilliseconds: deltas[Math.floor((deltas.length - 1) / 2)] ?? null,
      minDeltaMilliseconds: deltas[0] ?? null, maxDeltaMilliseconds: deltas.at(-1) ?? null,
      actionChanged: pairs.filter(pair => pair.actionChanged).length,
      depthChanged: pairs.filter(pair => pair.depthChanged).length },
  };
}

