import assert from 'node:assert/strict';
import { execFileSync, spawn } from 'node:child_process';
import { readFileSync, writeFileSync, appendFileSync, mkdirSync, existsSync } from 'node:fs';
import { createInterface } from 'node:readline';
import path from 'node:path';
import os from 'node:os';
import { checkEvasionPositions } from './benchmarks/checkEvasionPositions';
import { classify, reference, validatePosition, verifyReference, json, parse, hash, type Reference, type Result } from './benchmarks/tacticalDiagnostics';
import { observePv } from './benchmarks/terminalDistanceReference';
import { analyzeAlphaBetaSearch as fixed, analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch as timed } from '../src/domain/shogi/twoPlyAlphaBetaAi';
import { createCheckEvasionStatistics } from '../src/domain/shogi/quiescenceSearch';
import { protectSearchInput } from '../src/domain/shogi/selfPlayGame';
import { isPlayerInCheck } from '../src/domain/shogi/checkmate';
import { apply } from './benchmarks/terminalDistanceReference';
import { validatePartialRoot } from '../src/application/partialRootValidation';

const [mode, dirArg] = process.argv.slice(2);
const conditions = [ {id:'d1',depth:1,budget:null,repeats:1}, {id:'d4',depth:4,budget:null,repeats:1},
  {id:'100ms',depth:4,budget:100,repeats:3}, {id:'1000ms',depth:4,budget:1000,repeats:3} ];
const sources=['src/domain/shogi/quiescenceSearch.ts','src/domain/shogi/twoPlyAlphaBetaAi.ts',
  'src/domain/shogi/twoPlyMinimaxAi.ts','src/domain/shogi/legalActions.ts','src/domain/shogi/checkmate.ts',
  'src/domain/shogi/searchValue.ts','src/domain/shogi/transpositionTable.ts',
  'scripts/measure-check-evasion.ts','scripts/benchmarks/tacticalDiagnostics.ts',
  'scripts/benchmarks/tacticalPositions.ts','scripts/benchmarks/terminalDistanceReference.ts',
  'scripts/benchmarks/checkEvasionPositions.ts','scripts/benchmarks/checkEvasionReference.ts'];
const git=(...args:string[])=>execFileSync('git',args,{encoding:'utf8'}).trim();
const opts=(extra:number,stats=createCheckEvasionStatistics())=>({moveOrdering:'standard' as const,killerMoves:false,
  usePreviousIterationPv:false,useTranspositionTable:false,checkEvasionStatistics:stats,
  quiescence:{maxTacticalDepth:1,moveOrdering:'original' as const,maxCheckEvasionExtensions:extra}});
if(mode==='child') {
  const lines=createInterface({input:process.stdin});
  for await (const line of lines) {
    const {p,c,extra}=parse(line);
    const protectedInput=protectSearchInput(p.state), before=hash(p.state), stats=createCheckEvasionStatistics();
    const start=performance.now();
    const r=c.budget===null?fixed(protectedInput.snapshot,c.depth,undefined,undefined,opts(extra,stats)):
      timed(protectedInput.snapshot,c.depth,c.budget,undefined,undefined,opts(extra,stats));
    const callMs=performance.now()-start;
    assert.ok(!protectedInput.wasMutated()); assert.equal(hash(p.state),before);
    if(r.selectedEvaluation!==null) {
      assert.deepEqual(observePv(p.state,r.principalVariation).breakdown,r.evaluationBreakdown);
      assert.equal(r.selectedEvaluation,r.evaluationBreakdown!.total);
      assert.deepEqual(r.selectedAction,r.principalVariation[0]);
      assert.ok(r.principalVariation.length<=c.depth+1+extra);
    } else { assert.equal('resultSource' in r?r.resultSource:null,'fallback'); assert.equal(r.principalVariation.length,0); }
    if('resultSource' in r && r.resultSource==='partial-root') assert.ok(validatePartialRoot(p.state,r,1+extra));
    process.stdout.write(json({result:r,stats,callMs,apiMs:r.elapsedMilliseconds,
      overrunMs:c.budget===null?null:Math.max(0,callMs-c.budget)})+'\n');
  }
} else {
  assert.ok(dirArg && ['prepare','run','audit'].includes(mode),'prepare NEW_DIR | run DIR | audit DIR');
  const dir=path.resolve(dirArg), file=(s:string)=>path.join(dir,s);
  const write=(name:string,v:unknown)=>writeFileSync(file(name),json(v)+'\n',{flag:'wx'});
  if(mode==='prepare') {
    mkdirSync(dir); const positions=checkEvasionPositions();
    const validation=Object.fromEntries(positions.map(p=>[p.id,validatePosition(p)]));
    write('plan.json',{baseSha:'8248857d5c2fd4dea0a23e1b0de8f013c1ddc0f2',positions,positionHash:hash(positions),validation,
      conditions,extensions:[0,1,2],settings:opts(0),referenceLimits:{nodes:60000,milliseconds:8000},
      order:'serial position, condition, repetition; ABC/BCA/CAB rotates including warmup; one warmup per cell excluded',
      hardStopMs:60000, limitations:'timed ordinary/q counters cover completed passes; extra stats include interrupted calls. CPU affinity, power, OS/JIT/GC uncontrolled.',
      createdAt:new Date().toISOString()});
    const refs:Record<string,Reference>={};
    for(const p of positions) { refs[p.id]=reference(p); console.log('reference',p.id,refs[p.id].stopped); }
    write('references.json',refs);
  } else {
    const plan=parse(readFileSync(file('plan.json'),'utf8'));
    assert.equal(hash(checkEvasionPositions()),plan.positionHash); assert.deepEqual(plan.conditions,conditions);
    const refs=parse(readFileSync(file('references.json'),'utf8')) as Record<string,Reference>;
    for(const p of plan.positions) verifyReference(p,refs[p.id]);
    if(mode==='run') {
      assert.equal(git('diff','--name-only'),''); assert.equal(git('diff','--cached','--name-only'),'');
      assert.ok(!existsSync(file('environment.json')),'refuse overwriting measurements');
      write('sources.json',Object.fromEntries(sources.map(f=>[f,readFileSync(f,'utf8')])));
      write('environment.json',{sha:git('rev-parse','HEAD'),status:git('status','--porcelain'),planHash:hash(plan),refsHash:hash(refs),
        node:process.version,npm:execFileSync('npm.cmd',['--version'],{encoding:'utf8',shell:true}).trim(),os:`${os.platform()} ${os.release()} ${os.arch()}`,
        cpu:os.cpus()[0].model,sourceHashes:Object.fromEntries(sources.map(f=>[f,hash(readFileSync(f,'utf8'))])),startedAt:new Date().toISOString()});
      const workers=[0,1,2].map(()=>{
        const child=spawn(process.execPath,['--import','tsx',path.resolve('scripts/measure-check-evasion.ts'),'child'],{stdio:['pipe','pipe','inherit'],windowsHide:true});
        const lines=createInterface({input:child.stdout})[Symbol.asyncIterator](); return {child,lines};
      });
      let sequence=0;
      try {
        for(const p of plan.positions) for(const c of conditions) for(let rep=-1;rep<c.repeats;rep++) {
          const rotation=(sequence/3)%3;
          for(const extra of [rotation,(rotation+1)%3,(rotation+2)%3]) {
            const {child,lines}=workers[extra]; const phase=rep<0?'warmup':'measurement';
            child.stdin.write(json({p,c,extra})+'\n');
            let timer:ReturnType<typeof setTimeout>|undefined;
            const received=await Promise.race([lines.next(),new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(Error('60s hard-stop')),plan.hardStopMs);})]).finally(()=>clearTimeout(timer));
            assert.ok(!received.done,'measurement process ended early');
            const row={sequence:sequence++,position:p.id,condition:c.id,extra,rep,phase,status:'ok',...parse(received.value)};
            appendFileSync(file(phase==='warmup'?'warmup.jsonl':'raw.jsonl'),json(row)+'\n');
            console.log(row.sequence,p.id,c.id,extra,phase,row.callMs.toFixed(1));
          }
        }
        write('completed.json',{finishedAt:new Date().toISOString(),samples:sequence,rawHash:hash(readFileSync(file('raw.jsonl'),'utf8')),
          warmupHash:hash(readFileSync(file('warmup.jsonl'),'utf8'))});
      } catch(e) { write('failure.json',{error:String(e),sequence,at:new Date().toISOString()}); throw e; }
      finally { for(const w of workers) w.child.kill(); }
    } else {
      const env=parse(readFileSync(file('environment.json'),'utf8')), done=parse(readFileSync(file('completed.json'),'utf8'));
      assert.equal(env.planHash,hash(plan)); assert.equal(env.refsHash,hash(refs));
      const snapshot=parse(readFileSync(file('sources.json'),'utf8'));
      for(const [name,content] of Object.entries(snapshot)) assert.equal(env.sourceHashes[name],hash(content));
      assert.equal(done.rawHash,hash(readFileSync(file('raw.jsonl'),'utf8')));
      assert.equal(done.warmupHash,hash(readFileSync(file('warmup.jsonl'),'utf8')));
      const rows=readFileSync(file('raw.jsonl'),'utf8').trim().split(/\r?\n/).map(parse);
      const warmups=readFileSync(file('warmup.jsonl'),'utf8').trim().split(/\r?\n/).map(parse);
      assert.equal(warmups.length,plan.positions.length*conditions.length*3);
      assert.equal(done.samples,rows.length+warmups.length);
      const all=[...rows,...warmups].sort((a,b)=>a.sequence-b.sequence);
      assert.deepEqual(all.map(r=>r.sequence),Array.from({length:done.samples},(_,i)=>i));
      for(const row of all) {
        const c=conditions.find(c=>c.id===row.condition)!;
        assert.equal(row.status,'ok'); assert.ok(row.callMs>=0 && row.apiMs>=0);
        assert.equal(row.apiMs,row.result.elapsedMilliseconds);
        assert.equal(row.overrunMs,c.budget===null?null:Math.max(0,row.callMs-c.budget));
        assert.ok(row.stats.maxExtensionDepth<=row.extra);
        const p=plan.positions.find((p:{id:string})=>p.id===row.position);
        if(row.result.resultSource==='partial-root') assert.ok(validatePartialRoot(p.state,row.result,1+row.extra));
        if(row.result.selectedEvaluation!==null) assert.deepEqual(observePv(p.state,row.result.principalVariation).breakdown,row.result.evaluationBreakdown);
      }
      const expected=plan.positions.flatMap((p:{id:string})=>conditions.flatMap(c=>[0,1,2].flatMap(extra=>Array.from({length:c.repeats},(_,rep)=>`${p.id}/${c.id}/${extra}/${rep}`)))).sort();
      assert.deepEqual(rows.map(r=>`${r.position}/${r.condition}/${r.extra}/${r.rep}`).sort(),expected);
      const summary=rows.map(row=>{
        const p=plan.positions.find((p:{id:string})=>p.id===row.position), r=row.result as Result;
        if(r.selectedEvaluation!==null) assert.deepEqual(observePv(p.state,r.principalVariation).breakdown,r.evaluationBreakdown);
        let evasion:'not-in-check'|'success'|'failure'='not-in-check';
        if(isPlayerInCheck(p.state,p.state.turn)) {
          evasion=r.selectedAction && !isPlayerInCheck(apply(p.state,r.selectedAction),p.state.turn)?'success':'failure';
        }
        return {...row,...classify(p,refs[p.id],r),evasion,
          pvTerminalReason:r.selectedEvaluation===null?null:observePv(p.state,r.principalVariation).reason,
          terminalDiscovery:r.evaluationBreakdown?.terminal??'none',
          completedDepth:'completedDepth' in r?r.completedDepth:r.depth,
          resultSource:'resultSource' in r?r.resultSource:'fixed-depth',timedOut:'timedOut' in r?r.timedOut:false};
      });
      if(existsSync(file('summary.json'))) assert.deepEqual(parse(readFileSync(file('summary.json'),'utf8')),summary); else write('summary.json',summary);
      const table=['|condition|extra|n|match / mismatch / indeterminate|wall p50 / p95 ms|maximum overrun ms|completed depth sum|ordinary / q / extra nodes|',
        '|---|---:|---:|---|---|---:|---:|---|'];
      const quantile=(xs:number[],p:number)=>[...xs].sort((a,b)=>a-b)[Math.ceil(xs.length*p)-1];
      for(const c of conditions) for(const extra of [0,1,2]) {
        const rs=summary.filter(r=>r.condition===c.id&&r.extra===extra);
        const counts=['match','mismatch','indeterminate'].map(v=>rs.filter(r=>r.verdict===v).length).join(' / ');
        const sum=(f:(r:typeof rs[number])=>number)=>rs.reduce((n,r)=>n+f(r),0);
        table.push(`|${c.id}|${extra}|${rs.length}|${counts}|${quantile(rs.map(r=>r.callMs),.5).toFixed(3)} / ${quantile(rs.map(r=>r.callMs),.95).toFixed(3)}|${Math.max(...rs.map(r=>r.overrunMs??0)).toFixed(3)}|${sum(r=>r.completedDepth)}|${sum(r=>'totalVisitedPositionCount' in r.result?r.result.totalVisitedPositionCount:r.result.visitedPositionCount)} / ${sum(r=>'totalQuiescenceVisitedPositionCount' in r.result?r.result.totalQuiescenceVisitedPositionCount:r.result.quiescenceVisitedPositionCount)} / ${sum(r=>r.stats.visitedPositionCount)}|`);
      }
      const content=table.join('\n')+'\n';
      if(existsSync(file('results.md'))) assert.equal(readFileSync(file('results.md'),'utf8'),content);else writeFileSync(file('results.md'),content,{flag:'wx'});
      console.log(`Audited ${rows.length} measured samples, all PV and evaluations; summary regenerated.`);
    }
  }
}

scripts/measure-check-internals.ts:
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { closeSync, mkdirSync, openSync, writeSync } from 'node:fs';
import { arch, cpus, platform, release } from 'node:os';
import { dirname, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { SearchDiagnostics } from '../src/domain/shogi/searchDiagnostics';
import { getLegalActions } from '../src/domain/shogi/legalActions';
import { protectSearchInput } from '../src/domain/shogi/selfPlayGame';
import { resolveSearchEvaluationPreset } from '../src/domain/shogi/searchEvaluationPresets';
import { analyzeAlphaBetaSearch, analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch } from '../src/domain/shogi/twoPlyAlphaBetaAi';
import { replayPositions, SOURCE } from './benchmarks/timedDepthOneDiagnostics';
import { TARGETS, median } from './benchmarks/postRootDepthOne';
import type { CheckStage } from '../src/domain/shogi/checkInternalsDiagnostics';

const args = process.argv.slice(2);
assert.ok(args[0] === '--out' && args[1]?.endsWith('.jsonl') &&
  (args.length === 2 || (args.length === 3 && args[2] === '--smoke')),
  'Usage: npm run measure:check-internals -- --out PATH.jsonl [--smoke]');
const out = resolve(args[1]);
const smoke = args.includes('--smoke');
const warmups = smoke ? 1 : 2;
const runs = smoke ? 1 : 5;
const { positions, sourceSha256 } = replayPositions(SOURCE, smoke ? TARGETS.slice(0, 1) : TARGETS);
const evaluation = resolveSearchEvaluationPreset('standard');
const options = { moveOrdering: 'standard' as const,
  quiescence: { maxTacticalDepth: 1, moveOrdering: 'original' as const } };
const stages: readonly CheckStage[] = ['check', 'king', 'attackSearch', 'piece', 'pattern', 'step', 'ray'];
const parentPhases = ['q-board-simulate', 'q-board-own-check', 'q-drop-board-setup',
  'q-drop-own-check', 'q-drop-pawn-mate'] as const;
mkdirSync(dirname(out), { recursive: true });
const fd = openSync(out, 'wx');
const emit = (value: object) => writeSync(fd, JSON.stringify(value) + '\n');
try {
  const head = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
  emit({ type: 'config', schema: 'check-internals-v2', head, startedAt: new Date().toISOString(),
    source: SOURCE, sourceSha256, node: process.version,
    os: `${platform()} ${release()} ${arch()}`, cpu: cpus()[0]?.model ?? 'unknown',
    settings: { maxDepth: 4, timeLimitMilliseconds: 100, evaluation: 'standard',
      moveOrdering: 'standard', quiescence: options.quiescence }, warmups, runs, smoke,
    execution: 'one process, synchronous serial; OFF timed first, then fixed depth-one ON; each position rotates per run',
    timing: 'Internal inclusive is wall time within each stage. Exclusive is parent inclusive minus measured direct children; do not sum nested inclusive stages. Maximum single is inclusive. Fine-grained timing overhead is included in parent residual.' });
  for (const position of positions) emit({ type: 'position', id: position.id, band: position.band,
    stateSha256: position.stateSha256, positionKeySha256: position.positionKeySha256,
    historyLength: position.historyLength, sourceResult: position.sourceResult,
    rootCandidates: getLegalActions(position.state).length });

  const off: Array<{ positionId: string; phase: string; apiElapsedMilliseconds: number;
    resultSource: string; completedDepth: number; action: unknown;
    evaluation: number | null; rootCandidates: number }> = [];
  for (let index = 0; index < warmups + runs; index++) for (const position of positions) {
    const input = protectSearchInput(position.state);
    const result = analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch(input.snapshot,
      4, 100, evaluation, performance.now.bind(performance), options);
    assert.equal(input.wasMutated(), false);
    const row = { type: 'off', positionId: position.id,
      phase: index < warmups ? 'warmup' : 'measurement',
      run: index < warmups ? index + 1 : index - warmups + 1,
      apiElapsedMilliseconds: result.elapsedMilliseconds, resultSource: result.resultSource,
      completedDepth: result.completedDepth, action: result.selectedAction,
      evaluation: result.selectedEvaluation,
      rootCandidates: getLegalActions(position.state).length };
    off.push(row); emit(row);
  }

  const fixed: Array<{ positionId: string; phase: string; apiElapsedMilliseconds: number;
    action: unknown; evaluation: number | null;
    diagnostics: Pick<SearchDiagnostics, 'phases' | 'qLegalCounts' | 'finished'>;
    board: ReturnType<NonNullable<SearchDiagnostics['checkInternals']>['board']['snapshot']>;
    drop: ReturnType<NonNullable<SearchDiagnostics['checkInternals']>['drop']['snapshot']> }> = [];
  const fixedPlain: Array<{ positionId: string; phase: string; apiElapsedMilliseconds: number }> = [];
  for (let index = 0; index < warmups + runs; index++) for (const position of positions) {
    const phase = index < warmups ? 'warmup' : 'measurement';
    const run = index < warmups ? index + 1 : index - warmups + 1;
    const profile = () => {
      const input = protectSearchInput(position.state);
      const diagnostics = new SearchDiagnostics(false, false, true);
      const result = analyzeAlphaBetaSearch(input.snapshot, 1, evaluation,
        performance.now.bind(performance), options, diagnostics);
      assert.equal(input.wasMutated(), false);
      const row = { type: 'fixed', positionId: position.id, phase, run,
        apiElapsedMilliseconds: result.elapsedMilliseconds,
        action: result.selectedAction, evaluation: result.selectedEvaluation,
        diagnostics: { phases: diagnostics.phases, qLegalCounts: diagnostics.qLegalCounts,
          finished: diagnostics.finished },
        board: diagnostics.checkInternals!.board.snapshot(),
        drop: diagnostics.checkInternals!.drop.snapshot() };
      fixed.push(row); emit(row);
      return result;
    };
    const plain = () => {
      const input = protectSearchInput(position.state);
      const start = performance.now();
      const result = analyzeAlphaBetaSearch(input.snapshot, 1, evaluation, undefined, options);
      const elapsed = performance.now() - start;
      assert.equal(input.wasMutated(), false);
      fixedPlain.push({ positionId: position.id, phase, apiElapsedMilliseconds: elapsed });
      return { result, elapsed };
    };
    const [profiled, unprofiled] = index % 2 ? [profile(), plain()] : (() => {
      const unprofiled = plain(); return [profile(), unprofiled] as const;
    })();
    assert.deepEqual(profiled.selectedAction, unprofiled.result.selectedAction);
    assert.equal(profiled.selectedEvaluation, unprofiled.result.selectedEvaluation);
    emit({ type: 'fixed-plain-check', positionId: position.id, phase, run,
      apiElapsedMilliseconds: unprofiled.elapsed, sameAction: true, sameEvaluation: true });
  }
  emit({ type: 'end', endedAt: new Date().toISOString() });

  const lines = ['# 王手判定内部の分解計測', '',
    `基準HEAD: ${head}。保存棋譜SHA256: ${sourceSha256}。`,
    `環境: ${platform()} ${release()} ${arch()}、${cpus()[0]?.model ?? 'unknown'}、Node ${process.version}。`,
    `条件: ${positions.map(p => p.id).join('、')}、標準評価・標準手順序・静止探索追加1手・最大深さ4・100ms。同期直列、ウォームアップ${warmups}回、本測定${runs}回。`,
    '診断OFFは通常の100ms探索。診断ONは固定深さ1を完走する補助測定であり、100ms以内の完走を意味しない。両者のAPI時間から改善率を算出しない。固定深さ1のONとOFFも交互に対測定し、診断負荷の参考値にする。',
    '呼出経路: 盤上手は getQuiescenceLegalActionsWithDiagnostics → getLegalMoves → 局所盤面シミュレーション → isKingInCheckProfiled。持駒打ちは同じ列挙から getLegalDropSquares → validateDrop → 打った後の盤面 → isKingInCheckProfiled。どちらも findKingSquare → boolean専用攻撃元探索 → isPieceAttackingInternal → getPieceAttackPattern / step / ray を使う。通常の isKingInCheck → isSquareAttackedBy も最初の攻撃者で終了する。正確な countSquareAttackersBy は維持する。',
    '時間は各項目の中央値。排他時間は直接の子の包含時間を差し引く。最大単発は包含時間。親子の包含時間を合算しない。個々の駒に時計を置くため、子計時や集計処理の負荷は親の残余に含まれる。',
    '', '| 局面 | OFF API中央値ms | fallback | 完了深さ | 選択手 | root候補 | 固定深さ1 OFF/ON API中央値ms |',
    '| --- | ---: | ---: | --- | --- | ---: | ---: |'];
  const f = (n: number | null) => n?.toFixed(2) ?? '—';
  for (const position of positions) {
    const o = off.filter(row => row.positionId === position.id && row.phase === 'measurement');
    const d = fixed.filter(row => row.positionId === position.id && row.phase === 'measurement');
    const plain = fixedPlain.filter(row => row.positionId === position.id && row.phase === 'measurement');
    lines.push(`| ${position.id} | ${f(median(o.map(x => x.apiElapsedMilliseconds)))} | ${o.filter(x => x.resultSource === 'fallback').length}/${o.length} | ${o.map(x => x.completedDepth).join(',')} | ${JSON.stringify(o[0].action)} | ${o[0].rootCandidates} | ${f(median(plain.map(x => x.apiElapsedMilliseconds)))}/${f(median(d.map(x => x.apiElapsedMilliseconds)))} |`);
  }
  lines.push('', 'PR #170後の既存工程との関係: 以下の各局面では q-board-own-check が q-board-simulate より大きく、q-drop-own-check も q-drop-board-setup より大きい。各own-checkの内部は同じ呼出元のcheck包含 → king + attackSearch、attackSearch包含 → piece + 走査残余、piece包含 → pattern + step + ray + 残余として読む。',
    'dropの王手確認回数は4局面ともboardより多い。ただしdrop候補生成全体や100ms探索へこの固定深さ1の時間比を外挿しない。');
  for (const position of positions) {
    const own = fixed.filter(row => row.positionId === position.id && row.phase === 'measurement');
    lines.push('', `## ${position.id}: 固定深さ1診断ON`, '',
      '| 呼出元・項目 | 回数（各本） | 排他中央値ms | 包含中央値ms | 最大単発ms |',
      '| --- | --- | ---: | ---: | ---: |');
    for (const origin of ['board', 'drop'] as const) {
      const parent = origin === 'board' ? 'q-board-own-check' : 'q-drop-own-check';
      const p = own.map(row => row.diagnostics.phases[parent]);
      lines.push(`| ${parent} | ${p.map(x => x.calls).join(',')} | ${f(median(p.map(x => x.milliseconds)))} | ${f(median(p.map(x => x.inclusiveMilliseconds ?? 0)))} | ${f(Math.max(...p.map(x => x.maxMilliseconds ?? 0)))} |`);
      for (const stage of stages) {
        const rows = own.map(row => row[origin].timing[stage]);
        lines.push(`| ${origin}.${stage} | ${rows.map(x => x.calls).join(',')} | ${f(median(rows.map(x => x.exclusiveMilliseconds)))} | ${f(median(rows.map(x => x.inclusiveMilliseconds)))} | ${f(Math.max(...rows.map(x => x.maxMilliseconds)))} |`);
      }
      const counts = own.map(row => row[origin]);
      lines.push(`| ${origin} counts | checks ${counts.map(x => x.checks)} | scans ${counts.map(x => x.attackScans)} | squares ${counts.map(x => x.scannedSquares)} | pieces / calls ${counts.map(x => `${x.opponentPieces}/${x.pieceCalls}`)}; early exits ${counts.map(x => x.earlyExits)} |`);
    }
    lines.push('', '| 既存工程 | 排他中央値ms | 呼出回数（各本） |', '| --- | ---: | --- |');
    for (const phase of parentPhases) lines.push(`| ${phase} | ${f(median(own.map(x => x.diagnostics.phases[phase].milliseconds)))} | ${own.map(x => x.diagnostics.phases[phase].calls).join(',')} |`);
  }
  const attackSearchTotal = positions.reduce((sum, position) => sum +
    (median(fixed.filter(row => row.positionId === position.id && row.phase === 'measurement')
      .map(row => row.board.timing.attackSearch.inclusiveMilliseconds +
        row.drop.timing.attackSearch.inclusiveMilliseconds)) ?? 0), 0);
  lines.push('', `4局面のboard+drop別attackSearch包含中央値の合計は ${f(attackSearchTotal)}ms。細粒度計時負荷を含む。`,
    '攻撃元探索は攻撃者発見時に早期終了する。scansと実走査マス、早期終了件数、piece呼出数から実態を確認する。',
    '固定深さ1のON/OFF時間差は大きく、既存の探索診断と今回の高頻度計時の両方を含む。board/dropのprofiled check包含時間とq-own-check包含時間の差は呼出ラッパー、時計・集計負荷を含む。attackSearch排他にも子呼出計時の負荷が残るため、細粒度の値は概数として扱い、81マス走査の件数と併せて判断する。',
    '', `生データ: ${out.replaceAll('\\', '/')}`, '', '再実行: `npm run measure:check-internals -- --out docs/benchmarks/別名.jsonl`。既存ファイルは上書きしない。',
    '`npm run audit:check-internals -- docs/benchmarks/別名.jsonl`、`npm run check`、`git diff --check`。', '');
  const reportFd = openSync(out.slice(0, -6) + '.md', 'wx');
  try { writeSync(reportFd, lines.join('\n')); } finally { closeSync(reportFd); }
  console.log(`${out}: ${positions.length} positions, ${runs} measured runs`);
} finally { closeSync(fd); }

