import {loadPositions,qualityClassify} from './benchmarks/tacticalQuality';
import {evaluateSearchPositionBreakdown} from '../src/domain/shogi/twoPlyMinimaxAi';
import {resolveSearchEvaluationPreset} from '../src/domain/shogi/searchEvaluationPresets';
import type {TacticalPosition} from './benchmarks/tacticalPositions';
import type {Diagnosis} from './benchmarks/evasionBoundary';
const [mode,dir]=process.argv.slice(2);
if(mode==='child') {
 const req=parse(readFileSync(0,'utf8'));
 process.stdout.write(json(req.task?childTask(req.position,req.plan,req.task,req.allowance):diagnose(req.state,req.depth,req.extra,req.candidate,req.limits,{},req.q??1)));
} else {
 assert.ok(dir&&['prepare','run','audit'].includes(mode),'prepare NEW_DIR | run DIR | audit DIR');
 const file=(name:string)=>path.join(dir,name);
 const read=(name:string)=>parse(readFileSync(file(name),'utf8'));
 const write=(name:string,data:unknown)=>new EvidenceStore(dir,41943040,CLOSURE_BYTES).write(name,data);
 const git=(...args:string[])=>execFileSync('git',args,{encoding:'utf8'}).trim();
 const bytes=(f:string)=>createHash('sha256').update(readFileSync(f)).digest('hex');
 const old='docs/benchmarks/outcome-proof-20261022/run1';
 if(mode==='prepare') {
  assert.ok(!existsSync(dir)); mkdirSync(dir,{recursive:true});
  const original=parse(readFileSync(`${old}/plan.json`,'utf8'));
  const p=original.positions.find((p:TacticalPosition)=>p.id==='evasion') as TacticalPosition;
  loadPositions([p]); validatePosition(p);
  const prior=parse(readFileSync(`${old}/candidates.json`,'utf8')).filter((c:any)=>c.position==='evasion');
  assert.equal(prior.length,2);
  for(const c of prior) {assert.equal(hash(c.request.state),hash(p.state));assert.equal(c.result.status,'unknown');}
  const previous=parse(readFileSync('docs/benchmarks/tactical-quality-20261022/run1/plan.json','utf8'));
  assert.equal(hash(previous.positions.find((x:TacticalPosition)=>x.id==='evasion')),hash(p));
  const protectedFiles=git('ls-files','docs/benchmarks/outcome-proof-20261022','docs/benchmarks/tactical-quality-20261022').split(/\r?\n/);
  const ref=parse(readFileSync('docs/benchmarks/tactical-quality-20261022/run1/quality-references.json','utf8')).evasion;
  write('input.json',p);
  write('plan.json',{formatVersion:2,closureBytes:CLOSURE_BYTES,baseSha:'40b811dbaf685cd7fc86a3ef3a1defc5dadf14f0',pr206:{mergedAt:'2026-10-22T07:49:30Z',mergeSha:'40b811dbaf685cd7fc86a3ef3a1defc5dadf14f0'},
   inputHash:hash(p),stateHash:hash(p.state),origin:p.origin,historyLength:p.state.history.length,
   primaryCandidates:prior.map((c:any)=>c.request.candidate),candidates:[...prior.map((c:any)=>c.request.candidate),...getLegalActions(p.state).filter(a=>!prior.some((c:any)=>json(c.request.candidate)===json(a)))],priorOutcomes:prior.map((c:any)=>c.result.status),
   depths:[1,2,3,4],extensions:[0,1,2],settings:settings(0),limits,
   wholeMilliseconds:300000,wholeBytes:41943040,hardCallMilliseconds:12000,
   order:'serial depth, extra, root then candidates in saved #206 order; one call per cell; no repeats/warmups; diagnostic timings only',
   reference:{depth:3,nodes:6000,q:false,method:'existing qualityReference with forward/reverse full width'},
   boundary:{prefixPly:1,replies:prior.map((c:any)=>ref.candidates.find((r:any)=>json(r.action)===json(c.request.candidate)).value.pv[1]),
    conditions:['static','q1 captures/evasions','normal1+q1','forced saved reference reply normal1+q1'],
    limit:'same per-call node/time/trace cap; q1 public uses cooperative time check; boundary exact only if completed'},
   protectedHashes:Object.fromEntries(protectedFiles.map(f=>[f,bytes(f)])),createdAt:new Date().toISOString()});
 } else {
  const plan=read('plan.json'), p=read('input.json') as TacticalPosition;
  assert.equal(hash(p),plan.inputHash); assert.equal(hash(p.state),plan.stateHash); loadPositions([p]);
  if(plan.formatVersion===2) {
   if(mode==='run') {
    assert.ok(!existsSync(file('environment.json')),'refuse overwriting measurement');
    assert.equal(git('diff','--name-only'),'','commit code before measuring');assert.equal(git('diff','--cached','--name-only'),'');
    const deadline=new RunDeadline(plan.wholeMilliseconds);
    const files=git('ls-files','src','scripts','package.json','package-lock.json').split(/\r?\n/).filter(f=>!f.startsWith('src/test/'));
    const initial={
      'sources.json':utf8(Object.fromEntries(files.map(f=>[f,readFileSync(f,'utf8')]))),
      'environment.json':utf8({sourceSha:git('rev-parse','HEAD'),sourceHashes:Object.fromEntries(files.map(f=>[f,bytes(f)])),
        node:process.version,os:`${os.platform()} ${os.release()} ${os.arch()}`,cpu:os.cpus()[0].model,startedAt:new Date().toISOString(),planHash:hash(plan)})};
    const status=runBudgeted(dir,p,plan,initial,deadline);
    console.log(json(status));if(status.status!=='completed')process.exitCode=1;
   } else console.log(json(auditBudgeted(dir,p,plan)));
  } else {
  assert.equal(mode,'audit','legacy plans are audit-only; prepare a new v2 directory');
  const rows=Array.from({length:plan.depths.length*plan.extensions.length*(1+plan.candidates.length)},(_,i)=>read(`raw-${i}.json`)) as Diagnosis[];
  assert.deepEqual(rows.map(r=>[r.requestedDepth,r.extra,r.candidate]),plan.depths.flatMap((d:number)=>plan.extensions.flatMap((e:number)=>[null,...plan.candidates].map(c=>[d,e,c]))));
  const summary=aggregate(p.state,rows), ref=read('reference.json');
  const classifications=rows.filter(r=>r.candidate===null).map(r=>({depth:r.requestedDepth,extra:r.extra,...qualityClassify(p,ref,r.result)}));
  const comparisons=plan.depths.flatMap((depth:number)=>plan.extensions.map((extra:number)=>{
    const group=rows.filter(r=>r.requestedDepth===depth&&r.extra===extra), candidates=group.filter(r=>r.candidate);
    const completed=candidates.every(c=>c.result!==null);
    const values=candidates.map(c=>({action:c.candidate!,score:c.result?.selectedEvaluation??null,
      kind:c.valueKind,value:c.rootCandidates[0]?.value??null,originalIndex:getLegalActions(p.state).findIndex(a=>json(a)===json(c.candidate))}));
    const best=completed?values.reduce((a,b)=>compareSearchValues(a.value!,b.value!)>=0?a:b):null;
    const ties=best?values.filter(v=>compareSearchValues(v.value!,best.value!)===0).sort((a,b)=>a.originalIndex-b.originalIndex):[];
    if(completed&&group[0].result)assert.deepEqual(group[0].result.selectedAction,ties[0].action,'root must choose first original exact tie');
    return {depth,extra,completed,values,ties:ties.map(t=>t.action),rootSelected:group[0].result?.selectedAction??null};
  }));
  for(const b of read('boundary.json')) {
    const state=apply(p.state,b.prefix);assert.equal(hash(state),b.stateHash);
    assert.deepEqual(b.staticBreakdown,evaluateSearchPositionBreakdown(state,p.state.turn,resolveSearchEvaluationPreset('standard')));
    if(b.q)assert.deepEqual(observePv(state,b.q.principalVariation,p.state.turn).breakdown,b.q.evaluationBreakdown);
    for(const key of ['ordinary','forced']) if(b[key]) {
      aggregate(state,[b[key]]);
      if(b[key].result)assert.deepEqual(b[key+'Replay'],replay(state,b[key].result.principalVariation,1,0,1,1,p.state.turn));
    }
    assert.equal(b.originalRootScore,b.ordinary?.result?.selectedEvaluation==null?null:rootScore(b.ordinary.result.selectedEvaluation,state.turn,p.state.turn));
  }
  const result={summary,classifications,comparisons,completeCalls:rows.filter(r=>r.result).length,missingCalls:rows.filter(r=>!r.result).length};
  const env=read('environment.json'); assert.equal(env.planHash,hash(plan));
  for(const [f,h] of Object.entries(plan.protectedHashes))assert.equal(bytes(f),h,'old evidence modified');
  const snapshot=read('sources.json');
  for(const [f,h] of Object.entries(env.sourceHashes))assert.equal(createHash('sha256').update(snapshot[f]).digest('hex'),h);
  for(const [f,h] of Object.entries(read('manifest.json')))assert.equal(bytes(file(f)),h,'saved raw hash mismatch');
  assert.deepEqual(read('summary.json'),result,'saved reaggregation mismatch');
  const report=['|depth (root ply)|extra|root/forced destination|score|state|PV|leaf|','|---:|---:|---|---:|---|---|---|',...summary.map(r=>`|${r.depth}|${r.extra}|${r.candidate?json(r.candidate.to):'root'}|${r.score??'N/A'}|${r.source}|${r.pv.map(a=>a.kind==='move'?`${a.pieceType}(${a.from.row},${a.from.col})->(${a.to.row},${a.to.col}) ${a.promotion}`:`drop ${a.pieceType}`).join('; ')}|${r.leafReason??r.stop}|`)].join('\n')+'\n';
  assert.equal(readFileSync(file('comparison.md'),'utf8'),report);
  console.log(json({valid:true,summaryHash:hash(result),completeCalls:result.completeCalls,missingCalls:result.missingCalls}));
 }
 }
}

scripts/measure-fallback-quality.ts:
import assert from 'node:assert/strict';
import { execFileSync, spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { gzipSync, gunzipSync } from 'node:zlib';
import { cpus, platform, release, arch } from 'node:os';
import { resolve, join } from 'node:path';
import { performance } from 'node:perf_hooks';
import type { BoardState } from '../src/types/shogi';
import type { LegalAction } from '../src/domain/shogi/legalActions';
import { getLegalActions } from '../src/domain/shogi/legalActions';
import { protectSearchInput } from '../src/domain/shogi/selfPlayGame';
import { analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch, areLegalActionsEqual } from '../src/domain/shogi/twoPlyAlphaBetaAi';
import { options, evaluation, sha256, loadPositions, positionMetadata, verifyAction, reference,
  tacticalEvidence, summarize, finiteLoss, type TimedSample, type ReferenceRow } from './benchmarks/fallbackQuality';
import { SOURCE } from './benchmarks/timedDepthOneDiagnostics';
import { SearchDiagnostics } from '../src/domain/shogi/searchDiagnostics';

type Position = { id: string; state: BoardState; stateSha256: string };
const args = process.argv.slice(2);
const readPositions = (path: string) => JSON.parse((path.endsWith('.gz') ? gunzipSync(readFileSync(path)) : readFileSync(path)).toString('utf8'));
// A process limit can stop a fixed search even when synchronous domain work
// cannot reach a cooperative interruption check. No partial result is promoted.
if (args[0] === '--worker') {
  const position: Position = readPositions(args[2]).positions.find((p: Position) => p.id === args[3]);
  assert.ok(position); assert.equal(sha256(position.state), position.stateSha256);
  const start = performance.now();
  const data = args[1] === 'reference' ? reference(position.state)
    : tacticalEvidence(position.state, JSON.parse(args[4]) as LegalAction);
  console.log(JSON.stringify({ ...data, processWorkMs: performance.now() - start }, (_key, value) =>
    value === Infinity ? '+Infinity' : value === -Infinity ? '-Infinity' : value));
} else {
  assert.ok(args.length === 2 && ['extract', 'timed', 'reference', 'tactics', 'probe', 'audit'].includes(args[0]),
    'Usage: npx tsx scripts/measure-fallback-quality.ts extract|timed|reference|tactics|probe|audit DIRECTORY');
  const [mode, directory] = args;
  const dir = resolve(directory); mkdirSync(dir, { recursive: true });
  const positionsPath = join(dir, existsSync(join(dir, 'positions.json')) ? 'positions.json' : 'positions.json.gz');
  const readRows = (name: string) => readFileSync(join(dir, name), 'utf8').trim().split(/\r?\n/).map(line => JSON.parse(line));
  const write = (name: string, value: unknown) => writeFileSync(join(dir, name), JSON.stringify(value, null, 2) + '\n', { flag: 'wx' });
  const git = (...argv: string[]) => execFileSync('git', argv, { encoding: 'utf8' }).trim();
  const config = () => ({ type: 'config', schema: 'fallback-quality-v1', mode, startedAt: new Date().toISOString(),
    baseSha: git('rev-parse', 'origin/main'), head: git('rev-parse', 'HEAD'),
    dirty: git('status', '--porcelain=v1', '--untracked-files=all') !== '',
    status: git('status', '--porcelain=v1', '--untracked-files=all'),
    os: `${platform()} ${release()} ${arch()}`, cpu: cpus()[0]?.model, node: process.version,
    npm: execFileSync(process.platform === 'win32' ? 'npm.cmd' : 'npm', ['--version'], { encoding: 'utf8', shell: process.platform === 'win32' }).trim(),
    command: `npx tsx scripts/measure-fallback-quality.ts ${mode} ${directory}`,
    settings: { evaluation: 'standard', maxDepth: 4, budgets: [100, 1000], ...options },
    warmups: mode === 'timed' ? 2 : 0, runs: mode === 'timed' ? 5 : 1,
    diagnostics: mode === 'probe', input: 'protectSearchInput outside clock, same as saved self-play',
    execution: 'synchronous serial; timing in one process; reference/tactics in separate serial children with 120000ms process limit' });
  if (mode === 'extract') {
    const replay = loadPositions();
    const data = { config: config(), source: SOURCE, sourceSha256: replay.sourceSha256,
      selection: 'Existing seven depth-one positions plus g1-p44 (two evasions), g1-p93 and g3-p117 (prior long-tail); purposive, not random',
      positions: replay.positions.map(p => {
        const state = { ...p.state, recordId: 'replayed' };
        assert.equal(sha256(state), p.stateSha256);
        return { ...p, state, game: Number(p.id.match(/^g(\d+)/)![1]),
          nextPly: p.historyLength + 1, ...positionMetadata(state) };
      }) };
    assert.ok(!existsSync(join(dir, 'positions.json')));
    writeFileSync(join(dir, 'positions.json.gz'), gzipSync(JSON.stringify(data) + '\n'), { flag: 'wx' });
  } else {
    const document = readPositions(positionsPath);
    const positions: Position[] = document.positions;
    assert.equal(new Set(positions.map(p => p.id)).size, positions.length);
    for (const p of positions) assert.equal(sha256(p.state), p.stateSha256);
    if (mode === 'audit') {
      const timed = readRows('timed.jsonl'); const refs = readRows('reference.jsonl'); const tactics = readRows('tactics.jsonl');
      for (const rows of [timed, refs, tactics]) {
        assert.equal(rows[0].positionsFileSha256, sha256(document)); assert.equal(rows.at(-1).type, 'end');
      }
      const samples = timed.filter(r => r.type === 'sample') as TimedSample[];
      assert.equal(samples.length, positions.length * 2 * 7);
      for (const p of positions) for (const budget of [100, 1000]) for (const phase of ['warmup', 'measurement']) {
        const own = samples.filter(s => s.positionId === p.id && s.budget === budget && s.phase === phase);
        assert.equal(own.length, phase === 'warmup' ? 2 : 5);
        assert.equal(new Set(own.map(s => s.run)).size, own.length);
      }
      const references = refs.filter(r => r.type === 'reference') as ReferenceRow[];
      assert.equal(references.length, positions.length);
      assert.deepEqual(references.map(r => r.positionId).sort(), positions.map(p => p.id).sort());
      for (const ref of refs.filter(r => r.type === 'reference' && r.status === 'complete')) {
        const p = positions.find(p => p.id === ref.positionId)!;
        assert.equal(ref.result.depth, 1); assert.ok(ref.result.selectedAction);
        assert.equal(ref.bestScore, ref.result.selectedEvaluation);
        assert.equal(ref.fallbackScore, ref.fallbackEvaluation);
        assert.equal(ref.finiteLoss, finiteLoss(ref.bestScore, ref.fallbackScore));
        assert.equal(ref.actionMatches, areLegalActionsEqual(ref.fallback, ref.result.selectedAction));
        const legal = getLegalActions(p.state);
        assert.ok(areLegalActionsEqual(legal[0], ref.fallback));
        assert.ok(legal.some(a => areLegalActionsEqual(a, ref.result.selectedAction)));
      }
      const tacticalRows = tactics.filter(r => r.type === 'tactics');
      assert.deepEqual(tacticalRows.map(r => r.positionId).sort(), positions.map(p => p.id).sort());
      const summary = { schema: 'fallback-quality-summary-v1',
        inputByteSha256: Object.fromEntries(['timed.jsonl', 'reference.jsonl', 'tactics.jsonl', positionsPath.split(/[\\/]/).at(-1)!].map(name =>
          [name, createHash('sha256').update(readFileSync(join(dir, name))).digest('hex')])),
        uniquePositions: positions.length, measurementCalls: samples.filter(s => s.phase === 'measurement').length,
        rows: summarize(samples, references),
        tactics: tacticalRows.map(r => ({ positionId: r.positionId, status: r.status,
          missedMateInOne: r.missedMateInOne ?? null, allowsMateInOne: r.allowsMateInOne ?? null,
          alternativeAvoidsMateInOne: r.alternativeAvoidsMateInOne ?? null,
          betterOneReplyMaterialHorizon: r.betterOneReplyMaterialHorizon ?? null })) };
      if (existsSync(join(dir, 'summary.json'))) assert.deepEqual(JSON.parse(readFileSync(join(dir, 'summary.json'), 'utf8')), summary);
      else write('summary.json', summary);
      console.log('summary.json regenerated/verified from raw data');
    } else {
      const name = `${mode}.jsonl`;
      // Exclusive creation and immediate append preserve original rows on failure.
      writeFileSync(join(dir, name), JSON.stringify({ ...config(), positionsFileSha256: sha256(document) }) + '\n', { flag: 'wx' });
      const emit = (value: object) => writeFileSync(join(dir, name), JSON.stringify(value, (_key, value) =>
        value === Infinity ? '+Infinity' : value === -Infinity ? '-Infinity' : value) + '\n', { flag: 'a' });
      if (mode === 'probe') {
        // Supplement only: no performance or frequency aggregation with timed rows.
        for (const position of positions) for (const budget of [100, 1000]) {
          const input = protectSearchInput(position.state);
          const diagnostics = new SearchDiagnostics(false, false);
          const result = analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch(input.snapshot, 4, budget, evaluation, undefined, options, diagnostics);
          assert.equal(input.wasMutated(), false); verifyAction(position.state, result);
          emit({ type: 'probe', positionId: position.id, budget, resultSource: result.resultSource,
            completedDepth: result.completedDepth, depthOne: diagnostics.depthOne, phases: diagnostics.phases,
            interruptedStage: diagnostics.interruptedStage, deadline: diagnostics.deadlineObservation });
        }
      } else if (mode === 'timed') {
        for (const position of positions) {
          const before = sha256(position.state); const legal = getLegalActions(position.state);
          for (const budget of [100, 1000]) for (let index = 0; index < 7; index++) {
            const input = protectSearchInput(position.state);
            const start = performance.now();
            const result = analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch(input.snapshot, 4, budget, evaluation, undefined, options);
            const callMs = performance.now() - start;
            assert.equal(input.wasMutated(), false); verifyAction(position.state, result, legal);
            assert.equal(sha256(position.state), before);
            emit({ type: 'sample', positionId: position.id, budget, phase: index < 2 ? 'warmup' : 'measurement',
              run: index < 2 ? index + 1 : index - 1, callMs, apiMs: result.elapsedMilliseconds,
              overrunMs: Math.max(0, callMs - budget), resultSource: result.resultSource, completedDepth: result.completedDepth,
              timedOut: result.timedOut, action: result.selectedAction, inputUnchanged: true, result });
          }
          console.log(`timed ${position.id}`);
        }
      } else {
        const refs = mode === 'tactics' ? readRows('reference.jsonl') : [];
        for (const position of positions) {
          const ref = refs.find(r => r.type === 'reference' && r.positionId === position.id);
          if (mode === 'tactics' && ref?.status !== 'complete') {
            emit({ type: mode, positionId: position.id, status: 'missing-reference' }); continue;
          }
          const child = spawnSync(process.execPath, ['--import', 'tsx', 'scripts/measure-fallback-quality.ts', '--worker', mode,
            positionsPath, position.id, ...(mode === 'tactics' ? [JSON.stringify(ref.result.selectedAction)] : [])],
          { encoding: 'utf8', timeout: 120_000, maxBuffer: 16 * 1024 * 1024 });
          if (child.status !== 0 || child.error) emit({ type: mode, positionId: position.id,
            status: child.error && 'code' in child.error && child.error.code === 'ETIMEDOUT' ? 'process-timeout' : 'failed',
            error: child.error?.message ?? child.stderr, exitStatus: child.status, signal: child.signal });
          else emit({ type: mode, positionId: position.id, status: 'complete', ...JSON.parse(child.stdout) });
          console.log(`${mode} ${position.id}: ${child.status === 0 ? 'complete' : 'incomplete'}`);
        }
      }
      emit({ type: 'end', endedAt: new Date().toISOString() });
    }
  }
}

