  const cases = runOrderingSuite(modes, {}, undefined, entry => console.log(formatOrderingCase(entry)));
  for (const mode of modes) console.log(formatOrderingSummary(cases, mode));
  if (cases.some(c => !c.ok)) process.exitCode = 1;
} catch (error) {
