import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { closeSync, mkdirSync, openSync, writeSync } from 'node:fs';
import { arch, cpus, platform, release } from 'node:os';
import { dirname, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { SearchDiagnostics } from '../src/domain/shogi/searchDiagnostics';
import { protectSearchInput } from '../src/domain/shogi/selfPlayGame';
import { analyzeAlphaBetaSearch, analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch } from '../src/domain/shogi/twoPlyAlphaBetaAi';
import { resolveSearchEvaluationPreset } from '../src/domain/shogi/searchEvaluationPresets';
import { POSITION_IDS, replayPositions, summarizeSamples, type Sample } from './benchmarks/timedDepthOneDiagnostics';

const args = process.argv.slice(2);
const outputIndex = args.indexOf('--out');
if (outputIndex < 0 || !args[outputIndex + 1]) throw new Error('Usage: npm run measure:timed-depth-one -- --out PATH.jsonl [--smoke]');
const smoke = args.includes('--smoke');
const output = resolve(args[outputIndex + 1]);
if (!output.endsWith('.jsonl')) throw new Error('Output must end in .jsonl');
const unknown = args.filter((value, index) => value !== '--out' && value !== '--smoke' && index !== outputIndex + 1);
if (unknown.length) throw new Error(`Unknown arguments: ${unknown.join(' ')}`);
const reportPath = output.slice(0, -6) + '.md';
const warmups = smoke ? 1 : 2;
const measurements = smoke ? 1 : 5;
const { positions: allPositions, sourceSha256 } = replayPositions();
const positions = smoke ? allPositions.slice(0, 1) : allPositions;
const evaluation = resolveSearchEvaluationPreset('standard');
const options = { moveOrdering: 'standard' as const, quiescence: {
  maxTacticalDepth: 1, moveOrdering: 'original' as const } };

mkdirSync(dirname(output), { recursive: true });
const rawFd = openSync(output, 'wx');
let reportFd: number | undefined;
const emit = (row: object) => writeSync(rawFd, JSON.stringify(row) + '\n');
try {
  reportFd = openSync(reportPath, 'wx');
  const head = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
  const status = execFileSync('git', ['status', '--porcelain=v1', '--untracked-files=all'], { encoding: 'utf8' }).trim();
  emit({ type: 'config', startedAt: new Date().toISOString(), head, dirty: status !== '', status,
    source: 'docs/benchmarks/timed-fallback-100ms-20260924.jsonl', sourceSha256,
    node: process.version, os: `${platform()} ${release()} ${arch()}`, cpu: cpus()[0]?.model ?? 'unknown',
    execution: 'one-process-synchronous-serial-position-mode-probe-run', warmups, measurements,
    settings: { timeLimitMilliseconds: 100, maxDepth: 4, fixedDepth: 1, evaluation: 'standard', ...options },
    accounting: 'v2: exclusive nested spans; apiOther is API start to in-API finish minus measured spans; call time ends immediately after API return; legacy PR #156 files use v1 post-return finish',
  });
  for (const position of positions) emit({ type: 'position', id: position.id, band: position.band,
    game: Number(position.id.match(/^g(\d+)/)![1]), ply: position.historyLength + 1,
    historyLength: position.historyLength, stateSha256: position.stateSha256,
    positionKeySha256: position.positionKeySha256, sourceResult: position.sourceResult,
    sourceActualMilliseconds: position.sourceActualMilliseconds });
  const samples: Sample[] = [];
  for (const position of positions) {
    for (const mode of ['timed', 'fixed'] as const) {
      for (let index = 0; index < warmups + measurements; index++) {
        for (const probe of index % 2 === 0 ? [false, true] : [true, false]) {
          const diagnostics = probe ? new SearchDiagnostics() : undefined;
          const input = protectSearchInput(position.state);
          const start = performance.now();
          const result = mode === 'timed'
            ? analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch(input.snapshot, 4, 100, evaluation,
              performance.now.bind(performance), options, diagnostics)
            : analyzeAlphaBetaSearch(input.snapshot, 1, evaluation,
              performance.now.bind(performance), options, diagnostics);
          const actualElapsedMilliseconds = performance.now() - start;
          assert.equal(input.wasMutated(), false);
          const finished = diagnostics?.finished;
          const sample: Sample = { type: 'sample', positionId: position.id, band: position.band, mode, probe,
            phase: index < warmups ? 'warmup' : 'measurement', run: index < warmups ? index + 1 : index - warmups + 1,
            actualElapsedMilliseconds, apiElapsedMilliseconds: result.elapsedMilliseconds,
            completedDepth: 'completedDepth' in result ? result.completedDepth : result.depth,
            resultSource: 'resultSource' in result ? result.resultSource : 'fixed-complete',
            timedOut: 'timedOut' in result ? result.timedOut : false,
            action: result.selectedAction, evaluation: result.selectedEvaluation, pv: result.principalVariation,
            diagnostics: diagnostics && finished ? { phases: diagnostics.phases, ...finished,
              crossedDeadlinePhase: diagnostics.crossedDeadlinePhase,
              interruptedPhase: diagnostics.interruptedPhase } : null };
          samples.push(sample);
          emit(sample);
      }
      }
    }
    // Fixed-depth behavior must be invariant for every position and all runs.
    const fixed = samples.filter(s => s.positionId === position.id && s.mode === 'fixed');
    for (const sample of fixed.slice(1)) {
      assert.deepEqual([sample.action, sample.evaluation, sample.pv],
        [fixed[0].action, fixed[0].evaluation, fixed[0].pv], `${position.id}: diagnostic changed fixed result`);
    }
  }
  const summary = summarizeSamples(samples);
  emit({ type: 'summary', rows: summary });
  emit({ type: 'end', endedAt: new Date().toISOString() });
  const lines = ['# 深さ1・期限超過の工程診断', '',
    `コードSHA: ${head}。保存棋譜SHA256: ${sourceSha256}。${positions.length}局面、ウォームアップ${warmups}回、本測定${measurements}回。`,
    '実対局と同じ再帰Proxyで保護した探索入力を、呼び出し時計の外で構築します。時間は入れ子を差し引いた排他的な区分です。API内実時間は探索内の開始から返却直前まで、呼び出し全体の実時間は呼出直前から戻り直後まで。api-otherはAPI内実時間から排他的工程を差し引いた値です。PR #156の保存値は戻り後のfinishまでを含む旧定義です。',
    'deadlineをまたいだ工程と、次の確認で中断を検知した工程は異なり得ます。', '',
    '| 局面帯 | 条件 | 診断 | 本測定 | 深さ1完走 | fallback | 実時間中央値ms | 最大ms | 105ms超 |',
    '| --- | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |'];
  for (const row of summary.filter(r => r.samples)) lines.push(`| ${row.band} | ${row.mode} | ${row.probe ? 'ON' : 'OFF'} | ${row.samples} | ${row.depthOneCompletion} | ${row.fallback} | ${row.actualMedianMilliseconds?.toFixed(2) ?? 'n/a'} | ${row.actualMaxMilliseconds.toFixed(2)} | ${row.over105Count} |`);
  lines.push('', '## 工程別中央値（診断ON、ms）', '',
    '| 局面帯 | 条件 | root合法手 | 通常合法手 | 通常並べ替え | SEE | 通常着手適用 | 通常その他 | 静止探索 | APIその他 |',
    '| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |');
  for (const row of summary.filter(r => r.probe && r.samples)) {
    const v = row.phaseMedianMilliseconds!;
    lines.push(`| ${row.band} | ${row.mode} | ${v['root-legal']?.toFixed(2)} | ${v['normal-legal']?.toFixed(2)} | ${v['normal-order']?.toFixed(2)} | ${v.see?.toFixed(2)} | ${v['normal-execute']?.toFixed(2)} | ${v['normal-other']?.toFixed(2)} | ${v.quiescence?.toFixed(2)} | ${row.apiOtherMedianMilliseconds?.toFixed(2)} |`);
  }
  lines.push('', 'SEEは標準並べ替えでは呼ばれません。局面反復は独立した対局標本ではありません。OS、JIT、GC、同期処理の中断不能区間のため各中央値は当該PCでの観測です。', '');
  writeSync(reportFd, lines.join('\n'));
  console.log(`${output}: ${samples.length} samples; fixed-depth action/evaluation/PV identical`);
} finally {
  closeSync(rawFd);
  if (reportFd !== undefined) closeSync(reportFd);
}

scripts/measure-timed-fallback-self-play:
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { closeSync, mkdirSync, openSync, writeSync } from 'node:fs';
import { arch, cpus, platform, release } from 'node:os';
import { dirname, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { createInitialBoardState } from '../src/types/shogi';
import { createPositionKey } from '../src/domain/shogi/repetition';
import { DEFAULT_CONFIG, runMeasurement, summarizeGames, type MeasurementConfig, type MeasurementGame } from './benchmarks/timedFallbackSelfPlay';

function argumentsFromCli(argv: string[]): { output: string; config: MeasurementConfig } {
  const values: Record<string, string> = {};
  for (let i = 0; i < argv.length; i += 2) {
    const key = argv[i];
    if (!['--out', '--pairs', '--max-plies', '--limit-ms', '--max-depth', '--q-depth'].includes(key) ||
      !argv[i + 1] || values[key] !== undefined) throw new Error(`Invalid or duplicate argument: ${key}`);
    values[key] = argv[i + 1];
  }
  if (!values['--out']) throw new Error('Usage: npm run measure:timed-fallback-self-play -- --out PATH [--pairs N] [--max-plies N] [--limit-ms N] [--max-depth N] [--q-depth N]');
  const number = (key: string, fallback: number, min: number) => {
    if (values[key] === undefined) return fallback;
    const n = Number(values[key]);
    if (!Number.isSafeInteger(n) || n < min) throw new Error(`${key} must be an integer >= ${min}`);
    return n;
  };
  return { output: resolve(values['--out']), config: {
    ...DEFAULT_CONFIG,
    pairCount: number('--pairs', DEFAULT_CONFIG.pairCount, 1),
    maxPlies: number('--max-plies', DEFAULT_CONFIG.maxPlies, 1),
    timeLimitMilliseconds: number('--limit-ms', DEFAULT_CONFIG.timeLimitMilliseconds, 0),
    maxDepth: number('--max-depth', DEFAULT_CONFIG.maxDepth, 1),
    maxTacticalDepth: number('--q-depth', DEFAULT_CONFIG.maxTacticalDepth, 0),
  } };
}

const format = (n: number | null) => n === null ? 'n/a' : Number.isInteger(n) ? String(n) : n.toFixed(2);

function markdown(summary: ReturnType<typeof summarizeGames>, config: MeasurementConfig, elapsed: number): string {
  const lines = [
    '# 時間制限付き探索フォールバック実対局測定',
    '',
    `条件: 平手固定、${config.pairCount}ペア${summary.totalGames}局、最大${config.maxPlies}手、各手${config.timeLimitMilliseconds}ms、最大深さ${config.maxDepth}、評価${config.evaluationPreset}、通常手順${config.moveOrdering}、静止追加${config.maxTacticalDepth}手／${config.quiescenceMoveOrdering}。`,
    `実行: 同期直列、奇数ペアはAB→BA、偶数ペアはBA→AB。全体実経過 ${format(elapsed)}ms。`,
    `結果: A勝${summary.outcomes.aWins}、B勝${summary.outcomes.bWins}、引分${summary.outcomes.draws}、最大手数打切${summary.outcomes.maxPlies}、失敗${summary.outcomes.failures}。合計${summary.totalPlies}着手。`,
    '',
    '| 参加者 | 着手 | fallback | 率 | 実時間超過 | 超過中央値ms | 超過最大ms |',
    '| --- | ---: | ---: | ---: | ---: | ---: | ---: |',
  ];
  const participantDetails: string[] = [];
  for (const id of ['A', 'B'] as const) {
    const p = summary.participants[id] as ReturnType<typeof summarizeGames>['participants'][string];
    lines.push(`| ${id} | ${p.moves} | ${p.fallbackCount} | ${p.fallbackRate === null ? 'n/a' : (p.fallbackRate * 100).toFixed(1) + '%'} | ${p.actualOverLimit.count}/${p.moves} | ${format(p.actualOverLimit.medianExcessMilliseconds)} | ${format(p.actualOverLimit.maxExcessMilliseconds)} |`);
    participantDetails.push(`${id} fallback手数: ${p.fallbackPlies.join(', ') || 'なし'}。深さ分布 ${JSON.stringify(p.completedDepthDistribution)}、手数帯 ${JSON.stringify(p.fallbackByPlyBand)}、超過分布 ${JSON.stringify(p.actualOverLimit.distribution)}。`);
  }
  lines.push('', ...participantDetails.flatMap(detail => [detail, '']),
    `fallbackあり ${summary.byFallback.withFallback.games}局 ${JSON.stringify(summary.byFallback.withFallback.outcomes)}。fallbackなし ${summary.byFallback.withoutFallback.games}局 ${JSON.stringify(summary.byFallback.withoutFallback.outcomes)}。`, '',
    '| ペア/局 | 先手/後手 | 結果 | 手数 | A fallback/着手 | B fallback/着手 |',
    '| --- | --- | --- | ---: | ---: | ---: |');
  for (const game of summary.perGame) {
    const a = game.participants.A as ReturnType<typeof summarizeGames>['participants'][string];
    const b = game.participants.B as ReturnType<typeof summarizeGames>['participants'][string];
    lines.push(`| ${game.pairNumber}/${game.gameNumber} | ${game.sente}/${game.gote} | ${game.outcome} | ${game.plies} | ${a.fallbackCount}/${a.moves} | ${b.fallbackCount}/${b.moves} |`);
  }
  lines.push('', '同じ開始局面を反復するため独立標本ではありません。打切と失敗は勝敗・引分に含めません。少数対局から棋力差を判断しません。',
    '指定時間の一致だけでは公平な同一時間比較になりません。API内経過と呼び出し実経過を別々に記録し、超過率と分布を確認します。',
    '旧方式（PR #150以前）は100ms指定でも深さ1完走で大幅超過し得ます。旧方式の対局比較はこの測定に含めず、実経過時間を揃えた別課題とします。', '');
  return lines.join('\n');
}

let rawFd: number | undefined, reportFd: number | undefined;
try {
  const { output, config } = argumentsFromCli(process.argv.slice(2));
  const reportPath = output.replace(/\.jsonl$/i, '') + '.md';
  if (reportPath === output) throw new Error('--out must end in .jsonl');
  mkdirSync(dirname(output), { recursive: true });
  rawFd = openSync(output, 'wx');
  reportFd = openSync(reportPath, 'wx');
  const emit = (row: object) => writeSync(rawFd!, JSON.stringify(row, (_k, value: unknown) =>
    typeof value === 'number' && !Number.isFinite(value) ? String(value) : value) + '\n');
  const startedAt = new Date().toISOString();
  const started = performance.now();
  const initialState = createInitialBoardState();
  const head = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
  const status = execFileSync('git', ['status', '--porcelain=v1', '--untracked-files=all'], { encoding: 'utf8' }).trim();
  emit({ type: 'config', startedAt, head, dirty: status !== '', status,
    node: process.version, os: `${platform()} ${release()} ${arch()}`, cpu: cpus()[0]?.model ?? 'unknown',
    execution: 'synchronous-serial-alternating-pair-order', config,
    initialPosition: config.initialPosition,
    initialPositionKeySha256: createHash('sha256').update(createPositionKey(initialState)).digest('hex'),
    initialPositionStateSha256: createHash('sha256').update(JSON.stringify(initialState)).digest('hex'),
    denominator: 'successfully applied legal moves; terminal no-action states do not count as fallback moves' });
  const games: MeasurementGame[] = runMeasurement(config, { initialState, onGame: emit });
  const summary = summarizeGames(games);
  const elapsedMilliseconds = performance.now() - started;
  emit({ type: 'summary', ...summary, elapsedMilliseconds });
  emit({ type: 'end', endedAt: new Date().toISOString(), elapsedMilliseconds });
  writeSync(reportFd, markdown(summary, config, elapsedMilliseconds), undefined, 'utf8');
  console.log(`JSONL: ${output}\n集計: ${reportPath}\n${summary.totalGames}局 / ${summary.totalPlies}着手 / ${elapsedMilliseconds.toFixed(0)}ms`);
  if (summary.outcomes.failures) process.exitCode = 1;
} catch (error) {
  console.error(error);
  process.exitCode = 1;
} finally {
  if (rawFd !== undefined) closeSync(rawFd);
  if (reportFd !== undefined) closeSync(reportFd);
}

scripts/measure-timed-long-tail.ts:
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { closeSync, mkdirSync, openSync, writeSync } from 'node:fs';
import { arch, cpus, platform, release } from 'node:os';
import { dirname, resolve } from 'node:path';
import { PerformanceObserver, performance } from 'node:perf_hooks';
import { SearchDiagnostics } from '../src/domain/shogi/searchDiagnostics';
import { protectSearchInput } from '../src/domain/shogi/selfPlayGame';
import { createPositionKey } from '../src/domain/shogi/repetition';
import { analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch } from '../src/domain/shogi/twoPlyAlphaBetaAi';
import { resolveSearchEvaluationPreset } from '../src/domain/shogi/searchEvaluationPresets';
import { DEFAULT_CONFIG, runMeasurement } from './benchmarks/timedFallbackSelfPlay';
import { replayPositions } from './benchmarks/timedDepthOneDiagnostics';
import { summarizeLongTail, type LongTailSample } from './benchmarks/timedLongTail';

const args = process.argv.slice(2);
const allowed = new Set(['--out', '--pairs', '--max-plies', '--warmups', '--runs', '--probe']);
const values: Record<string, string> = {};
for (let index = 0; index < args.length; index += 2) {
  const key = args[index];
  if (!allowed.has(key) || !args[index + 1] || values[key] !== undefined) throw new Error(`Invalid argument: ${key}`);
  values[key] = args[index + 1];
}
if (!values['--out']?.endsWith('.jsonl')) throw new Error('Usage: npm run measure:timed-long-tail -- --out PATH.jsonl [--pairs N] [--max-plies N] [--warmups N] [--runs N] [--probe on|off]');
const integer = (key: string, fallback: number, min: number) => {
  const n = values[key] === undefined ? fallback : Number(values[key]);
  if (!Number.isSafeInteger(n) || n < min) throw new Error(`${key} must be an integer >= ${min}`);
  return n;
};
const output = resolve(values['--out']);
const report = output.slice(0, -6) + '.md';
const warmups = integer('--warmups', 1, 0);
const runs = integer('--runs', 3, 1);
const pairCount = integer('--pairs', 2, 1);
const maxPlies = integer('--max-plies', 120, 1);
const probe = values['--probe'] ?? 'on';
if (probe !== 'on' && probe !== 'off') throw new Error('--probe must be on or off');
const config = { ...DEFAULT_CONFIG, pairCount, maxPlies };
const head = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
const status = execFileSync('git', ['status', '--porcelain=v1', '--untracked-files=all'], { encoding: 'utf8' }).trim();
const { positions: allPositions, sourceSha256 } = replayPositions();
const positions = allPositions.filter(position => ['g1-p115', 'g3-p55', 'g4-p89'].includes(position.id));
assert.equal(positions.length, 3);

let gcObserver: PerformanceObserver | null = null;
let gcReason: string | null = null;
const gcEntries: Array<{ start: number; duration: number; kind: number; flags: number }> = [];
const recordGc = (entries: ReturnType<PerformanceObserver['takeRecords']>) => {
  for (const entry of entries) {
    const detail = (entry as typeof entry & { detail?: { kind?: number; flags?: number } }).detail;
    gcEntries.push({ start: entry.startTime, duration: entry.duration,
      kind: detail?.kind ?? -1, flags: detail?.flags ?? -1 });
  }
};
try {
  gcObserver = new PerformanceObserver(list => recordGc(list.getEntries()));
  gcObserver.observe({ entryTypes: ['gc'] });
} catch (error) { gcReason = String(error); gcObserver?.disconnect(); gcObserver = null; }
const heapAt = () => {
  try { return { at: performance.now(), bytes: process.memoryUsage().heapUsed }; }
  catch { return null; }
};
const sha = (value: string) => createHash('sha256').update(value).digest('hex');
type Before = { heap: ReturnType<typeof heapAt> };
const samples: LongTailSample[] = [];
function capture(input: { id: string; source: 'game' | 'replay'; gameId: string | null; ply: number;
  key: string; historyLength: number; phase: 'warmup' | 'measurement'; run: number;
  result: ReturnType<typeof analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch>;
  start: number; end: number; diagnostics: SearchDiagnostics | null; before: Before }): void {
  const after = heapAt();
  const diag = input.diagnostics;
  const callElapsedMilliseconds = input.end - input.start;
  samples.push({ type: 'sample', source: input.source, id: input.id, gameId: input.gameId,
    ply: input.ply, positionKeySha256: sha(input.key), historyLength: input.historyLength,
    probe: diag !== null, phase: input.phase, run: input.run,
    resultSource: input.result.resultSource, completedDepth: input.result.completedDepth,
    timedOut: input.result.timedOut, apiElapsedMilliseconds: input.result.elapsedMilliseconds,
    callElapsedMilliseconds, excessMilliseconds: callElapsedMilliseconds - config.timeLimitMilliseconds,
    action: input.result.selectedAction,
    diagnostics: diag?.finished ? { phases: diag.phases, ...diag.finished,
      crossedDeadlinePhase: diag.crossedDeadlinePhase, interruptedPhase: diag.interruptedPhase,
      longestCheckInterval: diag.longestCheckInterval, longestOperation: diag.longestOperation } : null,
    interval: { start: input.start, end: input.end },
    gc: { status: gcObserver ? 'available' : 'unavailable', reason: gcReason, events: [] },
    heap: { status: input.before.heap && after ? 'available' : 'unavailable',
      reason: input.before.heap && after ? null : 'process.memoryUsage failed', before: input.before.heap, after },
  });
}

mkdirSync(dirname(output), { recursive: true });
const rawFd = openSync(output, 'wx');
let reportFd: number | undefined;
const emit = (row: object) => writeSync(rawFd, JSON.stringify(row) + '\n');
try {
  reportFd = openSync(report, 'wx');
  emit({ type: 'config', schema: 'long-tail-v1', startedAt: new Date().toISOString(), head,
    dirty: status !== '', status, node: process.version, os: `${platform()} ${release()} ${arch()}`,
    cpu: cpus()[0]?.model ?? 'unknown', config, warmups, runs, probe, sourceSha256,
    execution: 'synchronous-serial; paired self-play then saved-position replay',
    timing: { api: 'search start clock to final clock inside API', call: 'immediately before invocation to immediately after return',
      apiOther: 'API start to API finish minus exclusive named spans; excludes caller and finish after return',
      gc: 'Node PerformanceObserver takeRecords after call; overlap on monotonic performance timeline',
      heap: 'process.memoryUsage.heapUsed samples before and after call; not an in-call peak' } });
  const games = runMeasurement(config, {
    probe: probe === 'on',
    beforeSearch: () => ({ heap: heapAt() } satisfies Before),
    onSearch: (position, result, timing) => capture({ id: '', source: 'game', gameId: null,
      ply: position.history.length + 1, key: createPositionKey(position), historyLength: position.history.length,
      phase: 'measurement', run: 1, result, start: timing.startedAt, end: timing.finishedAt,
      diagnostics: timing.diagnostics, before: timing.before as Before }),
  });
  let offset = 0;
  for (const game of games) {
    for (const ply of game.plies) {
      const sample = samples[offset++];
      assert.equal(sample.positionKeySha256, sha(ply.positionKey));
      assert.equal(sample.ply, ply.ply);
      sample.gameId = `g${game.executionIndex}`;
      sample.id = `g${game.executionIndex}-p${ply.ply}`;
    }
    emit(game);
  }
  assert.equal(offset, samples.length);
  const evaluation = resolveSearchEvaluationPreset('standard');
  for (const position of positions) {
    emit({ type: 'position', id: position.id, stateSha256: position.stateSha256,
      positionKeySha256: position.positionKeySha256, historyLength: position.historyLength,
      sourceActualMilliseconds: position.sourceActualMilliseconds });
    for (let index = 0; index < warmups + runs; index++) {
      for (const enabled of index % 2 ? [true, false] : [false, true]) {
        const input = protectSearchInput(position.state);
        const before: Before = { heap: heapAt() };
        const diagnostics = enabled ? new SearchDiagnostics() : undefined;
        const start = performance.now();
        const result = analyzeTimeLimitedIterativeDeepeningAlphaBetaSearch(input.snapshot, config.maxDepth,
          config.timeLimitMilliseconds, evaluation, performance.now.bind(performance),
          { moveOrdering: config.moveOrdering, quiescence: { maxTacticalDepth: config.maxTacticalDepth,
            moveOrdering: config.quiescenceMoveOrdering } }, diagnostics);
        const end = performance.now();
        assert.equal(input.wasMutated(), false);
        capture({ id: position.id, source: 'replay', gameId: null, ply: position.historyLength + 1,
          key: createPositionKey(position.state), historyLength: position.historyLength,
          phase: index < warmups ? 'warmup' : 'measurement', run: index < warmups ? index + 1 : index - warmups + 1,
          result, start, end, diagnostics: diagnostics ?? null, before });
      }
    }
  }
  // Node dispatches GC performance entries on an event-loop turn, while search
  // calls above are intentionally synchronous. Associate them only afterwards.
  await new Promise<void>(resolve => setImmediate(resolve));
  if (gcObserver) recordGc(gcObserver.takeRecords());
  for (const sample of samples) sample.gc.events = gcEntries.filter(entry =>
    entry.start < sample.interval.end && entry.start + entry.duration > sample.interval.start)
    .map(entry => ({ ...entry, overlapsSearch: true }));
  for (const sample of samples) emit(sample);
  const summary = summarizeLongTail(samples);
  emit({ type: 'summary', ...summary });
  emit({ type: 'end', endedAt: new Date().toISOString() });
  const top = samples.filter(sample => sample.phase === 'measurement')
    .sort((a, b) => b.callElapsedMilliseconds - a.callElapsedMilliseconds).slice(0, 10);
  const overlapping = samples.filter(sample => sample.phase === 'measurement' && sample.gc.events.length)
    .flatMap(sample => sample.gc.events.map(event => ({ id: sample.id, ...event }))).slice(0, 10);
  const heapByGame = games.map(game => {
    const own = samples.filter(sample => sample.gameId === `g${game.executionIndex}`);
    return `${game.executionIndex}: ${own[0]?.heap.before?.bytes ?? 'n/a'} → ${own.at(-1)?.heap.after?.bytes ?? 'n/a'} bytes`;
  });
  const lines = ['# 100ms探索の長い尾', '',
    `コード ${head}、dirty=${status !== ''}、Node ${process.version}、${platform()} ${release()} ${arch()}、${cpus()[0]?.model ?? 'unknown'}。`,
    `同期直列${games.length}局、最大${maxPlies}手、保存棋譜3局面のOFF/ON各${warmups}ウォームアップ・${runs}本測定。対局診断${probe}。`,
    'API内実時間は探索内の開始時計から返却直前の時計まで。呼び出し全体は呼出直前から戻り直後まで。api-otherはAPI内時間から排他的工程を差し引く。旧PR #156の保存値は戻り後の診断終了まで含むため比較時は旧定義として扱う。',
    `本測定${summary.samples}件、fallback ${summary.fallback}件、100ms超${summary.over100}件、105ms超${summary.over105}件。最大超過 ${JSON.stringify(summary.maxExcess)}。`,
    `最長期限確認間隔 ${JSON.stringify(summary.longestCheck)}。root内部の最長同期処理 ${JSON.stringify(summary.longestRootInterior)}。静止探索内部の最長同期処理 ${JSON.stringify(summary.longestQuiescenceInterior)}。`,
    `GC観測${summary.gcEvents}イベント、探索時間と重複${summary.gcOverlaps}件、GC欠測${summary.missingGc}件。重複は因果関係を示さない。ヒープ欠測${summary.missingHeap}件。最初と最後のサンプル ${JSON.stringify(summary.heapFirst)} → ${JSON.stringify(summary.heapLast)}。これらは処理中の最大値ではない。`,
    `保存棋譜局面の診断OFF/ON対応差（ON-OFF、ms）: ${JSON.stringify(summary.probePairs)}。単一順序の反復なので計測負荷だけを分離できない。`,
    '', '| 局面 | 由来 | 診断 | 実時間ms | API内ms | 超過ms | 深さ | GC重複 | 前後heap bytes |',
    '| --- | --- | --- | ---: | ---: | ---: | ---: | ---: | --- |',
    ...top.map(row => `| ${row.id} | ${row.resultSource} | ${row.probe ? 'ON' : 'OFF'} | ${row.callElapsedMilliseconds.toFixed(2)} | ${row.apiElapsedMilliseconds.toFixed(2)} | ${row.excessMilliseconds.toFixed(2)} | ${row.completedDepth} | ${row.gc.events.length} | ${row.heap.before?.bytes ?? 'n/a'} → ${row.heap.after?.bytes ?? 'n/a'} |`),
    '', `対局別ヒープ前後: ${heapByGame.join('、')}。`,
    `GC重複例（時刻はperformance時間軸のms）: ${JSON.stringify(overlapping)}。`,
    '保存棋譜局面は同一局面を反復する対応測定。診断時計読みと処理区分の追加により結果と時間は変わり得る。手数打切は勝敗・棋力の証拠ではない。'];
  writeSync(reportFd, lines.join('\n') + '\n');
  console.log(`${output}: ${games.length} games, ${summary.samples} measurement samples`);
} finally {
  gcObserver?.disconnect();
  closeSync(rawFd);
  if (reportFd !== undefined) closeSync(reportFd);
}

