// Optional external Playwright runtime; no application dependency is added.
// PLAYWRIGHT_MODULE may point to a preinstalled Playwright package directory.
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';

const require = createRequire(import.meta.url);
const { chromium } = require(process.env.PLAYWRIGHT_MODULE || 'playwright');
const url = process.argv[2] || 'http://127.0.0.1:4173/Shogi-App/';
const output = path.resolve(process.argv[3] || 'browser-evidence');
await mkdir(output, { recursive: true });
const browser = await chromium.launch({ headless: true });
const reports = [];
const issues = [];
try {
  const page = await browser.newPage();
  page.on('console', (message) => {
    if (['warning', 'error'].includes(message.type())) issues.push(`${message.type()}: ${message.text()}`);
  });
  page.on('pageerror', (error) => issues.push(`pageerror: ${error.message}`));
  // Observe the actual module Worker protocol without replacing its computation.
  await page.addInitScript(() => {
    window.presetWorkerEvidence = { requests: [], responses: [] };
    const NativeWorker = window.Worker;
    window.Worker = class extends NativeWorker {
      constructor(...args) {
        super(...args);
        this.addEventListener('message', (event) => window.presetWorkerEvidence.responses.push(event.data));
      }
      postMessage(...args) {
        window.presetWorkerEvidence.requests.push(structuredClone(args[0]));
        return super.postMessage(...args);
      }
    };
  });
  for (const width of [1440, 375, 320]) {
    await page.setViewportSize({ width, height: 1000 });
    await page.goto(url);
    const select = page.getByRole('combobox', { name: '評価プリセット' });
    // Resolve the ID/name mapping from rendered options, not a second preset list.
    const options = await select.locator('option').evaluateAll((nodes) => nodes.map((node) => ({ id: node.value, name: node.textContent })));
    assert.equal(options.length, 3);
    const defaultId = await select.inputValue();
    for (const { id, name } of options) {
      await page.reload();
      assert.equal(await select.inputValue(), defaultId);
      await select.selectOption(id);
      await page.getByText('AIの判断', { exact: true }).click();
      await page.getByRole('button', { name: '時間制限AIに指させる', exact: true }).click();
      assert.equal(await select.isDisabled(), true);
      await page.getByText(`評価設定: ${name}`, { exact: true }).waitFor();
      assert.equal(await select.isEnabled(), true);
      const evidence = await page.evaluate(() => {
        const select = document.querySelector('#evaluation-preset');
        const details = document.querySelector('details');
        const stats = document.querySelector('[aria-labelledby="ai-search-result-title"]');
        const boxes = [select, details, stats].map((node) => {
          const rect = node.getBoundingClientRect();
          return { left: rect.left, right: rect.right, client: node.clientWidth, scroll: node.scrollWidth };
        });
        return { ...window.presetWorkerEvidence, viewport: innerWidth, documentWidth: document.documentElement.scrollWidth, boxes };
      });
      assert.equal(evidence.requests.length, 1);
      assert.equal(evidence.responses.length, 1);
      const request = evidence.requests[0], response = evidence.responses[0], result = response.result;
      assert.equal(request.evaluationPresetId, id);
      assert.equal(response.requestId, request.requestId);
      assert.equal(result.evaluationPresetId, id);
      assert.equal(result.selectedEvaluation, result.evaluationBreakdown.total);
      assert.deepEqual(result.evaluationBreakdown, result.iterations.at(-1).evaluationBreakdown);
      assert.deepEqual(result.principalVariation, result.iterations.at(-1).principalVariation);
      const { material, pieceSquare, kingSafety, undefendedPieceSafety, total } = result.evaluationBreakdown;
      assert.equal(total, material + pieceSquare + kingSafety + undefendedPieceSafety);
      assert.ok(evidence.documentWidth <= width, `document overflow at ${width}`);
      for (const box of evidence.boxes) {
        assert.ok(box.left >= 0 && box.right <= width + 1 && box.scroll <= box.client + 1, JSON.stringify(box));
      }
      reports.push({ width, id, result, boxes: evidence.boxes, documentWidth: evidence.documentWidth });
      await page.screenshot({ path: path.join(output, `${width}-${id}.png`), fullPage: true });
    }
    // The synchronous two-ply action and candidates also use the selection.
    for (const { id, name } of options) {
      await page.reload();
      await select.selectOption(id);
      await page.getByText('AIの判断', { exact: true }).click();
      await page.getByRole('button', { name: '2手読みAIに指させる', exact: true }).click();
      await page.getByText(`評価設定: ${name}`, { exact: true }).waitFor();
      await page.getByText('上位候補手', { exact: true }).waitFor();
    }
  }
  assert.deepEqual(issues, [], 'Browser console warnings/errors');
  console.log(JSON.stringify({ searches: reports.length, synchronousSearches: 9, issues, widths: [1440, 375, 320] }));
} finally {
  await writeFile(path.join(output, 'browser-results.json'), JSON.stringify({ reports, issues }, null, 2));
  await browser.close();
}

scripts/verify-lockfile.mjs:
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * Validates lockfile integrity, exact matching dependencies with package.json, and checking forbidden lockfiles.
 * @param {string} [rootDir=process.cwd()]
 * @returns {{ valid: boolean, errors: string[], summary: { lockfileName: string, lockfileVersion: number | string, totalEntries: number, inspected: number, exceptions: number, missingVersion: number, missingResolved: number, missingIntegrity: number } }}
 */
export function validateLockfile(rootDir = process.cwd()) {
  const errors = [];

  // 1. Prohibited lockfile check
  const prohibitedLockfiles = ['bun.lock', 'bun.lockb', 'yarn.lock', 'pnpm-lock.yaml'];
  for (const file of prohibitedLockfiles) {
    if (fs.existsSync(path.resolve(rootDir, file))) {
      errors.push(`Prohibited lockfile found: ${file}`);
    }
  }

  // 2. package.json existence & parsing
  const pkgPath = path.resolve(rootDir, 'package.json');
  if (!fs.existsSync(pkgPath)) {
    return {
      valid: false,
      errors: ['package.json not found'],
      summary: {
        lockfileName: 'N/A',
        lockfileVersion: 'N/A',
        totalEntries: 0,
        inspected: 0,
        exceptions: 0,
        missingVersion: 0,
        missingResolved: 0,
        missingIntegrity: 0,
      },
    };
  }
  let pkg;
  try {
    pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
  } catch (err) {
    return {
      valid: false,
      errors: [`Failed to parse package.json: ${err.message}`],
      summary: {
        lockfileName: 'N/A',
        lockfileVersion: 'N/A',
        totalEntries: 0,
        inspected: 0,
        exceptions: 0,
        missingVersion: 0,
        missingResolved: 0,
        missingIntegrity: 0,
      },
    };
  }

  // 3. package-lock.json existence & parsing
  const lockPath = path.resolve(rootDir, 'package-lock.json');
  if (!fs.existsSync(lockPath)) {
    return {
      valid: false,
      errors: ['package-lock.json not found'],
      summary: {
        lockfileName: 'N/A',
        lockfileVersion: 'N/A',
        totalEntries: 0,
        inspected: 0,
        exceptions: 0,
        missingVersion: 0,
        missingResolved: 0,
        missingIntegrity: 0,
      },
    };
  }
  let lock;
  try {
    lock = JSON.parse(fs.readFileSync(lockPath, 'utf-8'));
  } catch (err) {
    return {
      valid: false,
      errors: [`Failed to parse package-lock.json: ${err.message}`],
      summary: {
        lockfileName: 'N/A',
        lockfileVersion: 'N/A',
        totalEntries: 0,
        inspected: 0,
        exceptions: 0,
        missingVersion: 0,
        missingResolved: 0,
        missingIntegrity: 0,
      },
    };
  }

  // 4. Root name & lockfileVersion validation (Compare with pkg.name)
  if (lock.name !== pkg.name) {
    errors.push(`package-lock.json root name mismatch: expected "${pkg.name}", got "${lock.name}"`);
  }
  if (lock.lockfileVersion !== 3) {
    errors.push(`package-lock.json lockfileVersion mismatch: expected 3, got ${lock.lockfileVersion}`);
  }

  // 5. Exact match comparison for dependencies and devDependencies
  const rootPackage = lock.packages?.[''] || {};

  function compareDeps(field, expectedDeps, actualDeps) {
    const expected = expectedDeps || {};
    const actual = actualDeps || {};

    const expectedKeys = Object.keys(expected);
    const actualKeys = Object.keys(actual);

    // Missing in lockfile or version mismatch
    for (const key of expectedKeys) {
      if (!(key in actual)) {
        errors.push(
          `Missing ${field} in package-lock.json root: "${key}" (expected "${expected[key]}", but was missing)`
        );
      } else if (actual[key] !== expected[key]) {
        errors.push(
          `Version mismatch for ${field} "${key}": expected "${expected[key]}", got "${actual[key]}" in package-lock.json root`
        );
      }
    }

    // Extra in lockfile
    for (const key of actualKeys) {
      if (!(key in expected)) {
        errors.push(
          `Extra ${field} in package-lock.json root: "${key}" (found "${actual[key]}", but not present in package.json)`
        );
      }
    }
  }

  compareDeps('dependencies', pkg.dependencies, rootPackage.dependencies || lock.dependencies);
  compareDeps('devDependencies', pkg.devDependencies, rootPackage.devDependencies || lock.devDependencies);

  // 6. Packages entries inspection (resolved & integrity validation)
  const packages = lock.packages || {};
  const allKeys = Object.keys(packages);
  const totalPackages = allKeys.length;

  let inspectedCount = 0;
  let exceptionCount = 0;
  let missingVersionCount = 0;
  let missingResolvedCount = 0;
  let missingIntegrityCount = 0;

  for (const [key, pkgInfo] of Object.entries(packages)) {
    if (key === '') {
      continue; // Root project package
    }

    // Legitimate exceptions: symbolic links or workspaces
    if (pkgInfo.link === true || pkgInfo.symlink === true) {
      exceptionCount++;
      continue;
    }

    inspectedCount++;

    if (!pkgInfo.version) {
      missingVersionCount++;
      errors.push(`Package "${key}" is missing "version" field`);
    }

    if (!pkgInfo.resolved) {
      missingResolvedCount++;
      errors.push(`Package "${key}" is missing "resolved" field`);
    }

    if (!pkgInfo.integrity) {
      missingIntegrityCount++;
      errors.push(`Package "${key}" is missing "integrity" field`);
    }
  }

  const summary = {
    lockfileName: lock.name,
    lockfileVersion: lock.lockfileVersion,
    totalEntries: totalPackages,
    inspected: inspectedCount,
    exceptions: exceptionCount,
    missingVersion: missingVersionCount,
    missingResolved: missingResolvedCount,
    missingIntegrity: missingIntegrityCount,
  };

  return {
    valid: errors.length === 0,
    errors,
    summary,
  };
}

export function printSummaryAndExit(result) {
  const { valid, errors, summary } = result;

  console.log('--- Lockfile Verification Summary ---');
  console.log(`Lockfile Name:           ${summary.lockfileName}`);
  console.log(`Lockfile Version:        ${summary.lockfileVersion}`);
  console.log(`Total Package Entries:   ${summary.totalEntries}`);
  console.log(`Inspected Registry Pkgs: ${summary.inspected}`);
  console.log(`Valid Exceptions:        ${summary.exceptions}`);
  console.log(`Missing "version":       ${summary.missingVersion}`);
  console.log(`Missing "resolved":      ${summary.missingResolved}`);
  console.log(`Missing "integrity":     ${summary.missingIntegrity}`);

  if (!valid) {
    console.error(`\n[verify:lock] FAILED with ${errors.length} error(s):`);
    for (const err of errors.slice(0, 10)) {
      console.error(` - ${err}`);
    }
    if (errors.length > 10) {
      console.error(` ... and ${errors.length - 10} more errors`);
    }
    process.exit(1);
  }

  console.log('\n[verify:lock] SUCCESS: package-lock.json is valid and complete.\n');
  process.exit(0);
}

// Run if executed directly
if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  const result = validateLockfile();
  printSummaryAndExit(result);
}

