/** Pure piece-drop validation, candidate generation, and simulation. */
import {
  BoardSquare,
  BoardState,
  MoveValidationResult,
  Piece,
  Player,
} from '../../types/shogi';
import { getForwardDelta, isKingInCheck, isKingInCheckProfiled } from './attacks';
import { cloneBoardSquares, getOpponent } from './boardStateUtils';
import { Coordinate, isWithinBoard } from './coordinates';
import { getLegalMoves } from './moves';
import { ILLEGAL_MOVE_MESSAGES } from './validation';
import type { ActionValidationProbe } from './actionValidationDiagnostics';
import type { SearchDiagnostics, DropPieceType } from './searchDiagnostics';

function getHands(state: BoardState): { current: Piece[]; opponent: Piece[] } {
  return state.turn === 'sente'
    ? { current: state.senteHand, opponent: state.goteHand }
    : { current: state.goteHand, opponent: state.senteHand };
}

function isDeadDrop(piece: Piece, to: Coordinate): boolean {
  if (piece.type !== 'pawn' && piece.type !== 'lance' && piece.type !== 'knight') {
    return false;
  }

  if (piece.player === 'sente') {
    return piece.type === 'knight' ? to.row <= 1 : to.row === 0;
  }
  return piece.type === 'knight' ? to.row >= 7 : to.row === 8;
}

function wouldBeNifu(squares: BoardSquare[][], piece: Piece, to: Coordinate): boolean {
  if (piece.type !== 'pawn') return false;

  return squares.some((row) => {
    const boardPiece = row[to.col].piece;
    return (
      boardPiece?.player === piece.player &&
      boardPiece.type === 'pawn' &&
      !boardPiece.isPromoted
    );
  });
}

/** Returns an immutable board copy with `piece` dropped at `to`. */
export function simulateDropSquares(
  squares: BoardSquare[][],
  piece: Piece,
  to: Coordinate
): BoardSquare[][] {
  const nextSquares = cloneBoardSquares(squares);
  if (!isWithinBoard(to.row, to.col)) return nextSquares;

  nextSquares[to.row][to.col].piece = {
    ...piece,
    isPromoted: false,
  };
  return nextSquares;
}

/** Validation only: readers never mutate shared rows, squares, or pieces. */
function prepareDropValidationSquares(
  squares: BoardSquare[][],
  piece: Piece,
  to: Coordinate
): BoardSquare[][] {
  const nextSquares = squares.slice();
  const destinationRow = squares[to.row].slice();
  nextSquares[to.row] = destinationRow;
  destinationRow[to.col] = {
    ...squares[to.row][to.col],
    piece: { ...piece, isPromoted: false },
  };
  return nextSquares;
}

function hasLegalBoardMoveResponseToPawnCheck(
  squares: BoardSquare[][],
  respondingPlayer: Player
): boolean {
  for (let row = 0; row < 9; row += 1) {
    for (let col = 0; col < 9; col += 1) {
      const piece = squares[row][col].piece;
      if (
        piece?.player === respondingPlayer &&
        getLegalMoves(squares, { row, col }, respondingPlayer).length > 0
      ) {
        return true;
      }
    }
  }
  return false;
}

function isPawnDropMateOnSimulatedBoard(
  squares: BoardSquare[][],
  droppingPlayer: Player
): boolean {
  const respondingPlayer = getOpponent(droppingPlayer);

  if (!isKingInCheck(squares, respondingPlayer)) {
    return false;
  }

  // A directly checking pawn cannot be answered by interposing a dropped piece.
  return !hasLegalBoardMoveResponseToPawnCheck(squares, respondingPlayer);
}

/** An unpromoted pawn checks only the square directly ahead of its drop. */
function droppedPawnDirectlyChecksKing(state: BoardState, to: Coordinate): boolean {
  const kingRow = to.row + getForwardDelta(state.turn);
  if (!isWithinBoard(kingRow, to.col)) return false;
  const pieceInFront = state.squares[kingRow][to.col].piece;
  return pieceInFront?.type === 'king' && pieceInFront.player === getOpponent(state.turn);
}

/** Validates one proposed drop in the documented rule order. */
export function validateDrop(
  state: BoardState,
  pieceId: string,
  to: Coordinate,
  diagnostics?: SearchDiagnostics,
  qDiagnostics?: SearchDiagnostics,
  probe?: ActionValidationProbe
): MoveValidationResult {
  if (state.status === 'ended') {
    return {
      isValid: false,
      reason: 'game_already_ended',
      message: ILLEGAL_MOVE_MESSAGES.game_already_ended,
    };
  }

  if (!isWithinBoard(to.row, to.col)) {
    return {
      isValid: false,
      reason: 'out_of_bounds',
      message: ILLEGAL_MOVE_MESSAGES.out_of_bounds,
    };
  }

  const hands = getHands(state);
  const piece = hands.current.find((candidate) => candidate.id === pieceId);
  if (!piece) {
    const opponentPiece = hands.opponent.find((candidate) => candidate.id === pieceId);
    const reason = opponentPiece ? 'not_own_hand_piece' : 'hand_piece_not_found';
    return {
      isValid: false,
      reason,
      message: ILLEGAL_MOVE_MESSAGES[reason],
    };
  }

  if (piece.player !== state.turn) {
    return {
      isValid: false,
      reason: 'not_own_hand_piece',
      message: ILLEGAL_MOVE_MESSAGES.not_own_hand_piece,
    };
  }

  if (piece.type === 'king') {
    return {
      isValid: false,
      reason: 'undroppable_piece',
      message: ILLEGAL_MOVE_MESSAGES.undroppable_piece,
    };
  }

  if (piece.isPromoted) {
    return {
      isValid: false,
      reason: 'invalid_hand_piece_state',
      message: ILLEGAL_MOVE_MESSAGES.invalid_hand_piece_state,
    };
  }

  if (state.squares[to.row][to.col].piece) {
    return {
      isValid: false,
      reason: 'occupied_drop_square',
      message: ILLEGAL_MOVE_MESSAGES.occupied_drop_square,
    };
  }

  if (isDeadDrop(piece, to)) {
    return {
      isValid: false,
      reason: 'dead_piece_drop',
      message: ILLEGAL_MOVE_MESSAGES.dead_piece_drop,
    };
  }

  if (wouldBeNifu(state.squares, piece, to)) {
    return {
      isValid: false,
      reason: 'nifu',
      message: ILLEGAL_MOVE_MESSAGES.nifu,
    };
  }

  const dropType = piece.type as DropPieceType;
  const simulatedSquares = probe
    ? probe.measure('board-setup', () => qDiagnostics
      ? qDiagnostics.measure('q-drop-board-setup', () => prepareDropValidationSquares(state.squares, piece, to))
      : diagnostics ? diagnostics.measureDropStage(dropType, 'drop-board-setup', () => prepareDropValidationSquares(state.squares, piece, to)) : prepareDropValidationSquares(state.squares, piece, to))
    : qDiagnostics
    ? qDiagnostics.measure('q-drop-board-setup', () => prepareDropValidationSquares(state.squares, piece, to))
    : diagnostics
    ? diagnostics.measureDropStage(dropType, 'drop-board-setup', () => prepareDropValidationSquares(state.squares, piece, to))
    : prepareDropValidationSquares(state.squares, piece, to);
  let ownCheck: boolean;
  if (qDiagnostics || diagnostics || probe) {
    const check = () => qDiagnostics?.checkInternals
      ? isKingInCheckProfiled(simulatedSquares, state.turn, qDiagnostics.checkInternals.drop)
      : isKingInCheck(simulatedSquares, state.turn);
    const checkMeasured = () => qDiagnostics
      ? qDiagnostics.measure('q-drop-own-check', check)
      : diagnostics ? diagnostics.measureDropStage(dropType, 'own-check', check) : check();
    ownCheck = probe ? probe.measure('own-check', checkMeasured) : checkMeasured();
  } else {
    ownCheck = isKingInCheck(simulatedSquares, state.turn);
  }
  if (ownCheck) {
    return {
      isValid: false,
      reason: 'self_check_unresolved',
      message: ILLEGAL_MOVE_MESSAGES.self_check_unresolved,
    };
  }

  if (
    piece.type === 'pawn' &&
    !piece.isPromoted &&
    droppedPawnDirectlyChecksKing(state, to) &&
    (probe
      ? probe.measure('pawn-drop-mate', () => qDiagnostics
      ? qDiagnostics.measure('q-drop-pawn-mate', () => isPawnDropMateOnSimulatedBoard(simulatedSquares, state.turn))
      : diagnostics ? diagnostics.measureDropStage(dropType, 'pawn-drop-mate', () => isPawnDropMateOnSimulatedBoard(simulatedSquares, state.turn)) : isPawnDropMateOnSimulatedBoard(simulatedSquares, state.turn))
      : qDiagnostics
      ? qDiagnostics.measure('q-drop-pawn-mate', () => isPawnDropMateOnSimulatedBoard(simulatedSquares, state.turn))
      : diagnostics
      ? diagnostics.measureDropStage(dropType, 'pawn-drop-mate', () => isPawnDropMateOnSimulatedBoard(simulatedSquares, state.turn))
      : isPawnDropMateOnSimulatedBoard(simulatedSquares, state.turn))
  ) {
    return {
      isValid: false,
      reason: 'pawn_drop_mate',
      message: ILLEGAL_MOVE_MESSAGES.pawn_drop_mate,
    };
  }

  return { isValid: true };
}

/** Exact existence query; shares validateDrop, including pawn-drop mate rules. */
export function hasLegalDropSquare(state: BoardState, pieceId: string): boolean {
  if (state.status === 'ended') return false;
  const piece = getHands(state).current.find(candidate => candidate.id === pieceId);
  if (!piece || piece.player !== state.turn || piece.type === 'king' || piece.isPromoted) return false;
  for (let row = 0; row < 9; row += 1) {
    for (let col = 0; col < 9; col += 1) {
      if (validateDrop(state, pieceId, { row, col }).isValid) return true;
    }
  }
  return false;
}

/** Returns every legal destination for the selected hand-piece ID. */
export function getLegalDropSquares(state: BoardState, pieceId: string, diagnostics?: SearchDiagnostics,
  qDiagnostics?: SearchDiagnostics, probe?: ActionValidationProbe): Coordinate[] {
  if (state.status === 'ended') return [];
  const piece = getHands(state).current.find((candidate) => candidate.id === pieceId);
  if (!piece || piece.player !== state.turn || piece.type === 'king' || piece.isPromoted) {
    return [];
  }

  const legalSquares: Coordinate[] = [];
  for (let row = 0; row < 9; row += 1) {
    for (let col = 0; col < 9; col += 1) {
      const to = { row, col };
      const result = probe ? probe.measure('validation', () => validateDrop(state, pieceId, to, diagnostics, qDiagnostics, probe))
        : validateDrop(state, pieceId, to, diagnostics, qDiagnostics);
      diagnostics?.recordDropResult(piece.type as DropPieceType, result.isValid ? undefined : result.reason);
      if (qDiagnostics) {
        qDiagnostics.qLegalCounts.dropCandidates++;
        if (result.isValid) qDiagnostics.qLegalCounts.dropLegal++;
      }
      if (result.isValid) {
        legalSquares.push(to);
      }
    }
  }
  return legalSquares;
}

src/domain/shogi/drops.ts:
/** Validated piece-drop execution and notation. */
import type { ActionValidationProbe } from './actionValidationDiagnostics';
import {
  BoardState,
  DropFoulRecord,
  DropMoveRecord,
  Piece,
  Player,
  ProposerType,
  ExecutionMode,
} from '../../types/shogi';
import { Coordinate, toCoordinateLabel } from './coordinates';
import {
  FoulLossExecutionResult,
  RejectedExecutionResult,
  finalizeIllegalProposal,
} from './executionPolicy';
import {
  determineDefaultExecutionMode,
  getPieceNotationKanji,
} from './gameState';
import {
  getLegalDropSquares,
  simulateDropSquares,
  validateDrop,
} from './dropRules';
import { ILLEGAL_MOVE_MESSAGES } from './validation';
import { adjudicateAfterLegalMove } from './adjudication';
import { normalizePositionHistory } from './repetition';
import {
  normalizePositionSnapshots,
  recordPositionSnapshotAfterLegalMove,
} from './replay';

export { getLegalDropSquares, simulateDropSquares, validateDrop } from './dropRules';

function getHands(state: BoardState): { current: Piece[]; opponent: Piece[] } {
  return state.turn === 'sente'
    ? { current: state.senteHand, opponent: state.goteHand }
    : { current: state.goteHand, opponent: state.senteHand };
}

export function generateDropNotation(player: Player, piece: Piece, to: Coordinate): string {
  const symbol = player === 'sente' ? '▲' : '△';
  return `${symbol}${toCoordinateLabel(to.row, to.col)}${getPieceNotationKanji(
    piece.type,
    player
  )}打`;
}

function internalApplyLegalDrop(
  state: BoardState,
  piece: Piece,
  to: Coordinate
): BoardState {
  const newSquares = simulateDropSquares(state.squares, piece, to);
  const nextSenteHand = [...state.senteHand];
  const nextGoteHand = [...state.goteHand];
  const activeHand = state.turn === 'sente' ? nextSenteHand : nextGoteHand;
  const pieceIndex = activeHand.findIndex((candidate) => candidate.id === piece.id);
  if (pieceIndex < 0) return state;
  activeHand.splice(pieceIndex, 1);

  const moveRecord: DropMoveRecord = {
    kind: 'drop',
    moveNumber: state.moveNumber,
    player: state.turn,
    from: null,
    to: { row: to.row, col: to.col },
    pieceType: piece.type,
    pieceId: piece.id,
    capturedPieceType: null,
    promotion: 'none',
    notation: generateDropNotation(state.turn, piece, to),
  };

  return {
    ...state,
    squares: newSquares,
    senteHand: nextSenteHand,
    goteHand: nextGoteHand,
    turn: state.turn === 'sente' ? 'gote' : 'sente',
    moveNumber: state.moveNumber + 1,
    status: 'active',
    history: [...state.history, moveRecord],
    lastMove: moveRecord,
    foulHistory: state.foulHistory ? [...state.foulHistory] : [],
  };
}

export interface ExecuteDropOptions {
  mode?: ExecutionMode;
  proposer?: ProposerType;
  engineName?: string;
}

export type DropExecutionResult =
  | { type: 'applied'; state: BoardState; move: DropMoveRecord }
  | RejectedExecutionResult
  | FoulLossExecutionResult;

/** Public validated execution API for piece drops. */
export function executeDrop(
  state: BoardState,
  pieceId: string,
  to: Coordinate,
  options: ExecuteDropOptions = {},
  probe?: ActionValidationProbe
): DropExecutionResult {
  const proposer = options.proposer ?? 'human';
  const mode = options.mode ?? determineDefaultExecutionMode(proposer);
  const validation = probe ? probe.measure('validation', () => validateDrop(state, pieceId, to, undefined, undefined, probe)) : validateDrop(state, pieceId, to);

  if (validation.isValid) {
    const piece = getHands(state).current.find((candidate) => candidate.id === pieceId);
    if (!piece) {
      return {
        type: 'rejected',
        state,
        reason: 'hand_piece_not_found',
        message: ILLEGAL_MOVE_MESSAGES.hand_piece_not_found,
      };
    }
    const normalizedState = normalizePositionSnapshots(normalizePositionHistory(state));
    const adjudicatedState = adjudicateAfterLegalMove(
      internalApplyLegalDrop(normalizedState, piece, to),
      state.turn
    );
    const nextState = recordPositionSnapshotAfterLegalMove(adjudicatedState);
    const move = nextState.lastMove;
    if (!move || move.kind !== 'drop') {
      return {
        type: 'rejected',
        state,
        reason: 'hand_piece_not_found',
        message: ILLEGAL_MOVE_MESSAGES.hand_piece_not_found,
      };
    }
    return { type: 'applied', state: nextState, move };
  }

  if (validation.reason === 'game_already_ended') {
    return {
      type: 'rejected',
      state,
      reason: validation.reason,
      message: validation.message,
    };
  }

  const allPieces = [...state.senteHand, ...state.goteHand];
  const pieceType = allPieces.find((candidate) => candidate.id === pieceId)?.type ?? null;
  const foulRecord: DropFoulRecord = {
    kind: 'drop',
    moveNumber: state.moveNumber,
    player: state.turn,
    from: null,
    to: { row: to?.row ?? -1, col: to?.col ?? -1 },
    pieceId,
    pieceType,
    reason: validation.reason,
    message: validation.message,
    proposer,
    engineName: options.engineName,
    timestamp: Date.now(),
  };

  return finalizeIllegalProposal(state, mode, foulRecord);
}

